  const [insuranceSimulationTier, setInsuranceSimulationTier] = useState<number>(0);
  const [isSimulatingPayout, setIsSimulatingPayout] = useState(false);
  const [payoutSuccess, setPayoutSuccess] = useState(false);

  const showToast = (msg: string) => {
    setToast(msg);
    setTimeout(() => setToast(null), 3000);
  };

  useEffect(() => {
    async function fetchAllCyclones() {
      try {
        const res = await fetch(`${getApiBaseUrl()}/api/history/search`);
        if (res.ok) {
          const data = await res.json();
          if (Array.isArray(data) && data.length > 0) {
            setCyclonesList(data.map((c: CatalogItem) => ({
              id: c.id,
              name: c.name.startsWith("Cyclone ") || c.name.startsWith("Deep Depression") || c.name.startsWith("Depression") || c.name.startsWith("Super Cyclone") || c.name.includes("Cyclone") ? c.name : `Cyclone ${c.name}`,
              basin: c.basin || "Bay of Bengal",
              category: c.max_category || "Cyclonic Storm",
              knots: c.knots ?? null,
            })));
          }
        }
      } catch (err) {
        console.error("Failed to load full cyclone list in reports", err);
      }
    }
    fetchAllCyclones();
  }, []);

  const [reportError, setReportError] = useState<string | null>(null);
  const [reportMode, setReportMode] = useState("EXPERIMENTAL_ANALYSIS");
  const fetchReportData = async (demo = false, signal?: AbortSignal) => {
    await Promise.resolve();
    if (signal?.aborted) return;
    setLoading(true);
    setReportError(null);
    setSystem(null);
    setBulletins([]);
    setSelectedBulletin(null);
    setCapXml("");
    setPortSignals([]);
    setAffectedDistricts([]);
    try {
      const params = new URLSearchParams();
      if (demo) params.set("simulate", "true");
      else if (selectedCycloneId) params.set("cyclone_id", selectedCycloneId);
      const res = await fetch(`${getApiBaseUrl()}/api/reports/bulletins?${params}`, { signal });
      if (!res.ok) throw new Error("Report unavailable");
      const data = await res.json();
      if (signal?.aborted) return;
      if (!data.system || !Array.isArray(data.bulletins)) throw new Error("Report unavailable");
      setSystem(data.system);
      setReportMode(data.mode);
      setBulletins(data.bulletins);
      setSelectedBulletin(data.bulletins[0] ?? null);
      setCapXml(data.cap_xml ?? "");
      setPortSignals(data.port_signals ?? []);
      setAffectedDistricts(data.affected_districts ?? []);
    } catch {
      if (signal?.aborted) return;
      setReportError("Report unavailable. Source data could not be loaded.");
    } finally {
      if (!signal?.aborted) setLoading(false);
    }
  };

  useEffect(() => {
    const controller = new AbortController();
    const task = window.setTimeout(() => void fetchReportData(false, controller.signal), 0);
    return () => { window.clearTimeout(task); controller.abort(); };
  }, [selectedCycloneId]);

  // Alert Badge Details
  const alertInfo = useMemo(() => {
    const rawKnots = system?.intensity_knots ?? null;
    const knots = getConvertedKnots(rawKnots);
    if (knots == null) return { level: "DATA_UNAVAILABLE", title: "Wind measurement not available", desc: "Hazard cannot be evaluated. Consult official agencies.", color: "text-slate-400", bg: "bg-slate-500/10", border: "border-slate-500/40", icon: <Info className="w-8 h-8" /> };
    if (knots >= 120) return { level: "RED", title: "Experimental high-wind scenario", desc: "Wind threshold category only. Landfall timing, surge, and evacuation requirements are not established by this report.", color: "text-red-400", bg: "bg-red-500/10", border: "border-red-500/40", icon: <AlertOctagon className="w-8 h-8 text-red-500 animate-pulse" /> };
    if (knots >= 90) return { level: "ORANGE", title: "Experimental wind assessment", desc: "Wind threshold category only. Consult official agencies for impact forecasts.", color: "text-orange-400", bg: "bg-orange-500/10", border: "border-orange-500/40", icon: <AlertTriangle className="w-8 h-8 text-orange-500 animate-bounce" /> };
    if (knots >= 48) return { level: "ORANGE", title: "Experimental wind assessment", desc: "Wind threshold category only. Rainfall and coastal impacts are not established.", color: "text-orange-400", bg: "bg-orange-500/10", border: "border-orange-500/40", icon: <AlertTriangle className="w-8 h-8 text-orange-500" /> };
    if (knots >= 34) return { level: "YELLOW", title: "Experimental wind assessment", desc: "Cyclonic Storm / Deep Depression. Sea conditions rough to very rough. Coastal squalls developing.", color: "text-yellow-400", bg: "bg-yellow-500/10", border: "border-yellow-500/40", icon: <AlertTriangle className="w-8 h-8 text-yellow-500" /> };
    return { level: "GREEN", title: "Experimental low-wind assessment", desc: "Low measured wind does not establish basin-wide calm or absence of other hazards.", color: "text-emerald-400", bg: "bg-emerald-500/10", border: "border-emerald-500/40", icon: <Info className="w-8 h-8 text-emerald-500" /> };
  }, [system, getConvertedKnots]);

  // Filtered Bulletins
  const filteredBulletins = useMemo(() => {
    return bulletins.filter((b) => {
      const matchesFilter = filterLevel === "ALL" || b.alert_level.toUpperCase() === filterLevel;
      const matchesSearch = !searchQuery.trim() || 
        b.title.toLowerCase().includes(searchQuery.toLowerCase()) || 
        b.category.toLowerCase().includes(searchQuery.toLowerCase()) ||
        b.full_text.toLowerCase().includes(searchQuery.toLowerCase());
      return matchesFilter && matchesSearch;
    });
  }, [bulletins, filterLevel, searchQuery]);

  const handleDownloadPdf = async () => {
    if (pdfLoading || !system) return;
    setPdfLoading(true);
    try {
      const activeSystem = system;
      if (!activeSystem) return;
      const rawKnots = activeSystem.intensity_knots;
      const convertedKnots = getConvertedKnots(rawKnots);
      const convertedCategory = getConvertedCategory(rawKnots, activeSystem.category || "Cyclonic Storm");

      const { generateCyclonePdfReport } = await import("@/lib/pdfReportGenerator");
      generateCyclonePdfReport({
        system: {
          ...activeSystem,
          intensity_knots: activeSystem.intensity_knots,
          category: convertedCategory,
        },
        alertInfo: alertInfo || {
          level: "ORANGE",
          title: "CYCLONE WARNING",
          desc: "Active threat assessment issued.",
        },
        sourceInfo: {
          type: sourceBadge.type,
          label: activeSystem.source ?? "Not available",
          shortLabel: sourceBadge.shortLabel,
          avgWindow: sourceBadge.avgWindow,
          scaleName: sourceBadge.scaleName,
        },
        bulletins: bulletins && bulletins.length > 0 ? bulletins : [],
        affectedDistricts,
        portSignals,

      });
      showToast(`Generated & downloaded Cyclone PDF advisory (${sourceBadge.shortLabel})!`);
    } catch (err: unknown) {
      console.error("PDF generation failed:", err);
      showToast(`PDF generation error: ${(err instanceof Error ? (err instanceof Error ? err.message : "Request failed") : "Request failed") || "Please check console"}`);
    } finally {
      setPdfLoading(false);
    }
  };

  const handleDownloadXml = () => {
    if (!capXml) { showToast("CAP exercise unavailable"); return; }
    const xmlContent = capXml;
    const blob = new Blob([xmlContent], { type: "application/xml" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `CAP-EXERCISE-${system?.name || "CYCLONE"}-${Date.now()}.xml`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    showToast("Downloaded OASIS CAP-CP XML Exercise Document");
  };

  const handleDownloadJson = () => {
    const rawKnots = system?.intensity_knots ?? null;
    const reportData = {
      timestamp: new Date().toISOString(),
      dataSource: sourceBadge,
      system: system ? {
        ...system,
        intensity_knots: getConvertedKnots(rawKnots),
        intensity_kmh: getConvertedKmh(rawKnots),
        category: getConvertedCategory(rawKnots, system.category)
      } : null,
      alertInfo,
      bulletins,
      affectedDistricts,
      portSignals,
      infrastructureExposure: {
        powerSubstations: POWER_SUBSTATIONS,
        evacuationRoutes: EVACUATION_ROUTES,
        medicalShelters: MEDICAL_SHELTERS,
        inundationZones: COASTAL_INUNDATION_ZONES
      },
      parametricInsuranceTriggers: PARAMETRIC_INSURANCE_TRIGGERS
    };
    const blob = new Blob([JSON.stringify(reportData, null, 2)], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = `CYCLONET-MET-REPORT-${system?.name || "CYCLONE"}.json`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    showToast("Downloaded Complete JSON Meteorological Report");
  };

  const handleCopyBulletin = (text: string) => {
    navigator.clipboard.writeText(text);
    showToast("Experimental Analysis Copied to Clipboard!");
  };

  // Simulate Multi-Channel Broadcast Dispatch
  const handleDispatchSimulation = async () => {
    if (dispatchStatus === "dispatching") return;
    setDispatchStatus("dispatching");
    setDispatchStep(1);

    setTimeout(() => setDispatchStep(2), 700);
    setTimeout(() => setDispatchStep(3), 1500);
    setTimeout(() => setDispatchStep(4), 2200);

    try {
      const data = await apiFetch<DispatchReceipt>("/api/alerts/broadcast-test", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          system_id: system?.id || selectedCycloneId,
          alert_type: alertType,
          channels: selectedChannels
        })
      });
      {
        setTimeout(() => {
          setDispatchReceipt(data);
          setDispatchStatus("completed");
          showToast("Exercise generated. No real broadcast was sent.");
        }, 2800);
      }
    } catch {
      setDispatchStatus("idle");
      setDispatchReceipt(null);
      showToast("Exercise request failed. No broadcast was sent.");
    }
  };

  const handleSimulateParametricPayout = () => {
    setIsSimulatingPayout(true);
    setPayoutSuccess(false);
    setTimeout(() => {
      setIsSimulatingPayout(false);
      setPayoutSuccess(true);
      showToast(`[SANDBOX SIMULATION] Parametric Liquidity Trigger Evaluated: Simulated disbursement of ${PARAMETRIC_INSURANCE_TRIGGERS[insuranceSimulationTier].hypotheticalPool}. (No live funds transferred)`);
    }, 1800);
  };

  const toggleChannel = (ch: string) => {
    if (selectedChannels.includes(ch)) {
      if (selectedChannels.length > 1) {
        setSelectedChannels(selectedChannels.filter(c => c !== ch));
      }
    } else {
      setSelectedChannels([...selectedChannels, ch]);
    }
  };

  if (loading) {
    return (
      <div className="flex flex-col items-center justify-center h-full min-h-[500px] gap-4">
        <div className="w-10 h-10 rounded-full border-3 border-primary/20 border-t-primary animate-spin" />
        <p className="text-sm font-medium text-muted-foreground animate-pulse">Compiling real-time meteorological bulletins and multi-hazard directives...</p>
      </div>
    );
  }

  if (!system) {
    return (
      <div className="flex flex-col items-center justify-center h-full min-h-[500px] text-muted-foreground gap-4">
        <Bell className="w-12 h-12 opacity-40 text-primary" />
        <p className="text-base font-semibold text-foreground">Report unavailable</p>
        <p className="text-sm text-muted-foreground max-w-md text-center">{reportError ?? "No report source is available."}</p>
        <button onClick={() => fetchReportData()} className="px-4 py-2 rounded-lg bg-primary text-primary-foreground">Retry</button>
        <button onClick={() => fetchReportData(true)}>Open synthetic demonstration report</button>
        <div className="flex flex-wrap gap-2 mt-2 max-w-2xl justify-center">
          {cyclonesList.slice(0, 8).map((s) => (
            <button
              key={s.id}
              onClick={() => selectCyclone(s.id, s.name)}
              className="px-3 py-1.5 rounded-lg bg-secondary/60 hover:bg-secondary border border-border text-xs font-medium text-foreground transition-all"
            >
              {s.name} ({s.category ? s.category.split(" ")[0] : "Storm"})
            </button>
          ))}
        </div>
      </div>
    );
  }

  const rawKnots = system.intensity_knots;
  const knots = getConvertedKnots(rawKnots);
  const kmh = getConvertedKmh(rawKnots);
  const gusts = system.gusts_kmh ?? null;
  const displayCategory = getConvertedCategory(rawKnots, system.category);
  const surgeM = null;
  const waveM = null;
  const pressureHpa = system.central_pressure_hpa ?? "Not available";

  return (
    <div className="flex flex-col gap-6 animate-in fade-in duration-500 pb-12 w-full">
      <p role="status" className="text-sm text-amber-400">{reportMode}: CycloNet experimental analysis — not an official warning. {system.is_simulation ? "Synthetic / historical replay." : "Source telemetry."} Source: {system.source ?? "Not available"}. Issue time: {system.observation_time_utc ?? "Not available"}. Retrieved: {system.retrieved_at ?? "Not available"}.</p>
      {/* ── Top Header & Operational Action Bar ────────────────────────────── */}
      <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 glass-card p-6 border-border/80 relative overflow-hidden">
        <div className="absolute -right-20 -top-20 w-64 h-64 bg-primary/10 rounded-full blur-3xl pointer-events-none" />
        
        <div className="space-y-1.5 z-10">
          <div className="flex flex-wrap items-center gap-2.5">
            <span className="flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-bold uppercase tracking-wider bg-primary/15 text-primary border border-primary/30">
              <span className="w-2 h-2 rounded-full bg-primary animate-ping" />
              RSMC / IMD Warning Center
            </span>
            <span className={`flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-bold uppercase tracking-wider border ${sourceBadge.badgeClass}`}>
              {sourceBadge.shortLabel}
            </span>
            <span className={`px-2.5 py-1 rounded-full text-xs font-black uppercase tracking-wider ${alertInfo.bg} ${alertInfo.color} border ${alertInfo.border}`}>
              {alertInfo.level} — EXPERIMENTAL ACTIVE
            </span>
            <span className="text-xs text-muted-foreground font-mono">
              Fix: {system.lat.toFixed(1)}°N, {system.lon.toFixed(1)}°E • {system.basin}
            </span>
          </div>
          <h1 className="text-2xl sm:text-3xl font-heading font-black text-foreground tracking-tight">
            Alerts & Meteorological Reports
          </h1>
          <p className="text-sm text-muted-foreground">
            CycloNet experimental analyses, OASIS CAP-CP warning protocols (Exercise), infrastructure exposure, and parametric insurance scenarios.
          </p>
        </div>

        {/* Action Buttons */}
        <div className="flex flex-wrap items-center gap-2 z-10">
          {/* Storm Switcher Dropdown */}
          <select
            value={selectedCycloneId || system.id}
            onChange={(e) => {
              const storm = cyclonesList.find(s => s.id === e.target.value);
              selectCyclone(e.target.value, storm?.name);
            }}
            className="px-3 py-2 bg-secondary/80 hover:bg-secondary border border-border rounded-lg text-xs font-semibold text-foreground focus:outline-none focus:ring-1 focus:ring-primary cursor-pointer transition-colors"
          >
            {cyclonesList.map((s) => (
              <option key={s.id} value={s.id}>
                {s.name} {s.category ? `(${s.category})` : ""}
              </option>
            ))}
          </select>

          {/* Export JSON */}
          <button
            onClick={handleDownloadJson}
            title="Download full JSON dataset with infrastructure and parametric triggers"
            className="flex items-center gap-1.5 px-3 py-2 bg-secondary/70 hover:bg-secondary border border-border rounded-lg text-xs font-medium text-foreground transition-colors"
          >
            <Download className="w-3.5 h-3.5" /> JSON
          </button>

          {/* Export CAP-CP XML */}
          <button
            onClick={handleDownloadXml}
            title="Download OASIS CAP-CP v1.2 XML Document (Exercise Status)"
            className="flex items-center gap-1.5 px-3 py-2 bg-secondary/70 hover:bg-secondary border border-border rounded-lg text-xs font-medium text-foreground transition-colors"
          >
            <ShieldAlert className="w-3.5 h-3.5 text-orange-400" /> CAP XML
          </button>

          {/* Download PDF */}
          <button
            onClick={handleDownloadPdf}
            disabled={pdfLoading}
            aria-busy={pdfLoading}
            title="Download Cyclone Meteorological PDF Advisory (Exercise Simulation)"
            className="flex items-center gap-1.5 px-3.5 py-2 bg-primary text-primary-foreground hover:bg-primary/90 font-bold rounded-lg text-xs shadow-lg shadow-primary/20 transition-all cursor-pointer"
          >
            <Download className="w-3.5 h-3.5" /> {pdfLoading ? "Preparing PDF…" : "Download PDF"}
          </button>
        </div>
      </div>

      {/* Toast Notification */}
      {toast && (
        <div className="fixed bottom-6 right-6 bg-zinc-900 text-white border border-primary/40 px-4 py-3 rounded-xl shadow-2xl shadow-primary/20 animate-in slide-in-from-bottom-3 z-50 flex items-center gap-2.5 text-sm font-medium">
          <CheckCircle2 className="w-4 h-4 text-primary shrink-0" />
          {toast}
        </div>
      )}

      {/* ── Main Multi-Hazard Warning Banner ───────────────────────────────── */}
      <div className={`glass-card p-6 md:p-7 border-2 ${alertInfo.border} ${alertInfo.bg} transition-all`}>
        <div className="flex flex-col md:flex-row items-start md:items-center justify-between gap-6">
          <div className="flex items-start gap-5">
            <div className="p-3.5 rounded-2xl bg-background/80 border border-border shadow-inner shrink-0">
              {alertInfo.icon}
            </div>
            <div className="space-y-1.5">
              <div className="flex flex-wrap items-center gap-2">
                <span className={`text-xl sm:text-2xl font-black tracking-wider ${alertInfo.color}`}>
                  {alertInfo.level} — EXPERIMENTAL
                </span>
                <span className="px-2.5 py-0.5 rounded text-xs font-bold bg-background text-foreground uppercase border border-border">
                  {displayCategory}
                </span>
                <span className="px-2 py-0.5 rounded text-xs font-medium bg-secondary text-muted-foreground">
                  System: {system.name}
                </span>
              </div>
              <h2 className="text-lg sm:text-xl font-bold text-foreground">{alertInfo.title}</h2>
              <p className="text-sm text-muted-foreground leading-relaxed max-w-4xl">
                {alertInfo.desc} The system is sustaining winds of <strong className="text-foreground">{knots ?? "Not available"} knots ({kmh ?? "Not available"} km/h)</strong> with gusts up to <strong className="text-foreground">{gusts ?? "Not available"} km/h</strong> and central pressure of <strong className="text-foreground">{pressureHpa} hPa</strong>.
              </p>
            </div>
          </div>

          <div className="flex md:flex-col items-center md:items-end justify-between w-full md:w-auto shrink-0 gap-2 border-t md:border-t-0 border-border/40 pt-4 md:pt-0">
            <div className="text-left md:text-right">
              <p className="text-xs text-muted-foreground uppercase tracking-wider font-semibold">Max Sustained Wind ({sourceBadge.shortLabel})</p>
              <p className="text-2xl sm:text-3xl font-mono font-black text-primary">{kmh ?? "Not available"} <span className="text-sm font-normal text-muted-foreground">km/h</span></p>
            </div>
            <div className="text-right">
              <span className="text-xs font-bold text-orange-400 bg-orange-500/10 border border-orange-500/20 px-2 py-1 rounded">
                Gusts {gusts ?? "Not available"} km/h
              </span>
            </div>
          </div>
        </div>
      </div>

      {/* ── Navigation Tabs ────────────────────────────────────────────────── */}
      <div className="flex items-center justify-between gap-2 border-b border-border/80 pb-3 overflow-x-auto scrollbar-none">
        <div className="flex items-center gap-2">
          <button
            onClick={() => setActiveTab("hazards")}
            className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-semibold transition-all shrink-0 cursor-pointer ${
              activeTab === "hazards"
                ? "bg-primary text-primary-foreground shadow-md shadow-primary/20"
                : "text-muted-foreground hover:text-foreground hover:bg-secondary/60"
            }`}
          >
            <ShieldAlert className="w-4 h-4" /> Hazard Matrix & Threats
          </button>

          <button
            onClick={() => setActiveTab("bulletins")}
            className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-semibold transition-all shrink-0 cursor-pointer ${
              activeTab === "bulletins"
                ? "bg-primary text-primary-foreground shadow-md shadow-primary/20"
                : "text-muted-foreground hover:text-foreground hover:bg-secondary/60"
            }`}
          >
            <FileText className="w-4 h-4" /> Experimental Analyses ({bulletins.length})
          </button>

          <button
            onClick={() => setActiveTab("broadcast")}
            className={`flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-semibold transition-all shrink-0 cursor-pointer ${
              activeTab === "broadcast"
                ? "bg-primary text-primary-foreground shadow-md shadow-primary/20"
                : "text-muted-foreground hover:text-foreground hover:bg-secondary/60"
            }`}
          >
            <Radio className="w-4 h-4 text-red-400 animate-pulse" /> Emergency Broadcast Hub
          </button>
        </div>

        <a
          href={system ? `/infrastructure?cyclone_id=${encodeURIComponent(system.id)}` : "/infrastructure"}
          className="hidden sm:flex items-center gap-1.5 px-3.5 py-1.5 rounded-lg bg-secondary/80 hover:bg-secondary border border-border text-xs font-semibold text-foreground transition-all shrink-0 shadow-xs hover:scale-[1.02]"
        >
          <Building2 className="w-3.5 h-3.5 text-amber-400" />
          <span>Infrastructure & Resilience →</span>
        </a>
      </div>

      {/* ══════════════════════════════════════════════════════════════════════
          TAB 1: MULTI-HAZARD MATRIX & COASTAL THREATS
         ══════════════════════════════════════════════════════════════════════ */}
      {activeTab === "hazards" && (
        <div className="space-y-6 animate-in fade-in duration-300">
          {/* 4-Stage Warning Timeline */}
          <div className="glass-card p-6">
            <h3 className="text-base font-bold text-foreground mb-4 flex items-center gap-2">
              <Layers className="w-4 h-4 text-primary" />
              IMD 4-Stage Tropical Cyclone Early Warning Protocol
            </h3>
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-3">
              <div className={`p-4 rounded-xl border ${knots != null && knots >= 34 ? "bg-yellow-500/10 border-yellow-500/30 text-yellow-400" : "bg-secondary/30 border-border text-muted-foreground"}`}>
                <div className="flex items-center justify-between mb-1.5">
                  <span className="text-xs font-mono font-bold">STAGE 1 (72h Prior)</span>
                  <span className="text-xs font-bold px-1.5 py-0.5 rounded bg-yellow-500/20 text-yellow-300">YELLOW</span>
                </div>
                <p className="font-bold text-sm text-foreground">Pre-Cyclone Watch</p>
                <p className="text-xs text-muted-foreground mt-1">Deep depression detection in oceanic basin. Marine warnings issued to off-shore vessels.</p>
              </div>

              <div className={`p-4 rounded-xl border ${knots != null && knots >= 48 ? "bg-orange-500/10 border-orange-500/30 text-orange-400" : "bg-secondary/30 border-border text-muted-foreground"}`}>
                <div className="flex items-center justify-between mb-1.5">
                  <span className="text-xs font-mono font-bold">STAGE 2 (48h Prior)</span>
                  <span className="text-xs font-bold px-1.5 py-0.5 rounded bg-orange-500/20 text-orange-300">ORANGE</span>
                </div>
                <p className="font-bold text-sm text-foreground">Cyclone Alert</p>
                <p className="text-xs text-muted-foreground mt-1">Gale wind warning and coastal district mobilization. Fishing operations suspended.</p>
              </div>

              <div className={`p-4 rounded-xl border ${knots != null && knots >= 64 ? "bg-red-500/10 border-red-500/40 text-red-400 ring-1 ring-red-500/30" : "bg-secondary/30 border-border text-muted-foreground"}`}>
                <div className="flex items-center justify-between mb-1.5">
                  <span className="text-xs font-mono font-bold">STAGE 3 (24h Prior)</span>
                  <span className="text-xs font-bold px-1.5 py-0.5 rounded bg-red-500/20 text-red-300">RED</span>
                </div>
                <p className="font-bold text-sm text-foreground">Cyclone Warning</p>
                <p className="text-xs text-muted-foreground mt-1">Landfall sector identified. Consult local disaster management authorities for evacuation directives.</p>
              </div>

              <div className={`p-4 rounded-xl border ${knots != null && knots >= 64 ? "bg-red-500/5 border-red-500/20 text-foreground" : "bg-secondary/30 border-border text-muted-foreground"}`}>
                <div className="flex items-center justify-between mb-1.5">
                  <span className="text-xs font-mono font-bold">STAGE 4 (12h Prior)</span>
                  <span className="text-xs font-bold px-1.5 py-0.5 rounded bg-zinc-800 text-zinc-300">OUTLOOK</span>
                </div>
                <p className="font-bold text-sm text-foreground">Post-Landfall Outlook</p>
                <p className="text-xs text-muted-foreground mt-1">Inland severe gale path, flash flooding, and heavy debris clearance operations.</p>
              </div>
            </div>
          </div>

          {/* Multi-Hazard Parameter Cards */}
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
            {/* Wind Hazard */}
            <div className="glass-card p-5 border-border space-y-3">
              <div className="flex items-center justify-between">
                <div className="p-2.5 rounded-xl bg-blue-500/10 text-blue-400 border border-blue-500/20">
                  <Wind className="w-5 h-5" />
                </div>
                <span className="text-xs font-mono font-bold text-blue-400 bg-blue-500/10 px-2 py-0.5 rounded">Gale Force</span>
              </div>
              <div>
                <p className="text-xs text-muted-foreground font-medium">Sustained Wind & Gusts</p>
                <p className="text-2xl font-mono font-black text-foreground">{kmh ?? "Not available"} <span className="text-xs font-normal text-muted-foreground">km/h</span></p>
                <p className="text-xs text-orange-400 font-semibold mt-0.5">Peak Gusts: {gusts ?? "Not available"} km/h</p>
              </div>
              <p className="text-xs text-muted-foreground leading-relaxed border-t border-border/50 pt-2">
                Uprooting of large trees, extensive damage to kutcha houses, and disruption of power lines.
              </p>
            </div>

            {/* Storm Surge */}
            <div className="glass-card p-5 border-border space-y-3">
              <div className="flex items-center justify-between">
                <div className="p-2.5 rounded-xl bg-cyan-500/10 text-cyan-400 border border-cyan-500/20">
                  <Waves className="w-5 h-5" />
                </div>
                <span className="text-xs font-mono font-bold text-cyan-400 bg-cyan-500/10 px-2 py-0.5 rounded">Inundation</span>
              </div>
              <div>
                <p className="text-xs text-muted-foreground font-medium">Observed Storm Surge</p>
                <p className="text-2xl font-mono font-black text-foreground">{surgeM ?? "Not available"} <span className="text-xs font-normal text-muted-foreground">meters</span></p>
                <p className="text-xs text-cyan-400 font-semibold mt-0.5">Wave Height: {waveM ?? "Not available"}m</p>
              </div>
              <p className="text-xs text-muted-foreground leading-relaxed border-t border-border/50 pt-2">
                Flood extent cannot be inferred from wind alone. No observed inundation data is supplied.
              </p>
            </div>

            {/* Heavy Rain & Flash Flood */}
            <div className="glass-card p-5 border-border space-y-3">
              <div className="flex items-center justify-between">
                <div className="p-2.5 rounded-xl bg-indigo-500/10 text-indigo-400 border border-indigo-500/20">
                  <CloudRain className="w-5 h-5" />
                </div>
                <span className="text-xs font-mono font-bold text-indigo-400 bg-indigo-500/10 px-2 py-0.5 rounded">Red Alert</span>
              </div>
              <div>
                <p className="text-xs text-muted-foreground font-medium">24h Rainfall Forecast</p>
                <p className="text-2xl font-mono font-black text-foreground">Not available <span className="text-xs font-normal text-muted-foreground">mm</span></p>
                <p className="text-xs text-indigo-400 font-semibold mt-0.5">Rainfall observation not available</p>
              </div>
              <p className="text-xs text-muted-foreground leading-relaxed border-t border-border/50 pt-2">
                No verified rainfall or flood forecast is supplied.
              </p>
            </div>

            {/* Port & Maritime Warning */}
            <div className="glass-card p-5 border-border space-y-3">
              <div className="flex items-center justify-between">
                <div className="p-2.5 rounded-xl bg-amber-500/10 text-amber-400 border border-amber-500/20">
                  <Anchor className="w-5 h-5" />
                </div>
                <span className="text-xs font-mono font-bold text-amber-400 bg-amber-500/10 px-2 py-0.5 rounded">Not available</span>
              </div>
              <div>
                <p className="text-xs text-muted-foreground font-medium">Nautical Port Warning</p>
                <p className="text-base font-bold text-foreground truncate">{portSignals[0]?.signal || "Not available"}</p>
                <p className="text-xs text-amber-400 font-semibold mt-0.5">Consult port authorities</p>
              </div>
              <p className="text-xs text-muted-foreground leading-relaxed border-t border-border/50 pt-2">
                No verified port directive is available. Consult official port authorities.
              </p>
            </div>
          </div>

          {/* Vulnerable Coastal Districts Table */}
          <div className="glass-card p-6">
            <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4">
              <div>
                <h3 className="text-base font-bold text-foreground flex items-center gap-2">
                  <MapPin className="w-4 h-4 text-primary" />
                  High-Risk Coastal Districts & Evacuation Readiness
                </h3>
                <p className="text-xs text-muted-foreground mt-0.5">
                  No independently verified district exposure data is supplied.
                </p>
              </div>
              <span className="text-xs font-medium text-primary bg-primary/10 px-3 py-1 rounded-full border border-primary/20 w-fit">
                {affectedDistricts.length} Verified district records
              </span>
            </div>

            <div className="overflow-x-auto">
              <table className="w-full text-left text-sm">
                <thead>
                  <tr className="border-b border-border/80 text-xs text-muted-foreground uppercase font-semibold">
                    <th className="pb-3 pl-2">District / Jurisdiction</th>
                    <th className="pb-3">State</th>
                    <th className="pb-3">Threat Rating</th>
                    <th className="pb-3">Cyclone Shelters</th>
                    <th className="pb-3 text-right pr-2">Evacuation Order</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-border/40 font-mono text-xs">
                  {affectedDistricts.map((d, i) => (
                    <tr key={i} className="hover:bg-secondary/30 transition-colors">
                      <td className="py-3.5 pl-2 font-sans font-semibold text-foreground flex items-center gap-2">
                        <span className="w-1.5 h-1.5 rounded-full bg-primary shrink-0" />
                        {d.district}
                      </td>
                      <td className="py-3.5 font-sans text-muted-foreground">{d.state}</td>
                      <td className="py-3.5">
                        <span className={`px-2.5 py-1 rounded text-[11px] font-bold ${
                          d.risk.includes("Extremely") ? "bg-red-500/15 text-red-400 border border-red-500/30" :
                          d.risk.includes("High") ? "bg-orange-500/15 text-orange-400 border border-orange-500/30" :
                          "bg-yellow-500/15 text-yellow-400 border border-yellow-500/30"
                        }`}>
                          {d.risk}
                        </span>
                      </td>
                      <td className="py-3.5 text-foreground">{d.shelters}</td>
                      <td className="py-3.5 text-right pr-2">
                        <span className={`px-2.5 py-1 rounded text-[11px] font-bold ${
                          d.evacuation.includes("Hazard") ? "bg-red-500/20 text-red-400 border border-red-500/30 font-sans" :
                          "bg-secondary text-foreground font-sans"
                        }`}>
                          {d.evacuation}
                        </span>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        </div>
      )}

      {/* ══════════════════════════════════════════════════════════════════════
          TAB 2: OFFICIAL METEOROLOGICAL BULLETINS (RSMC / IMD)
         ══════════════════════════════════════════════════════════════════════ */}
      {activeTab === "bulletins" && (
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 animate-in fade-in duration-300">
          {/* Bulletin Selector & Filter Column */}
          <div className="lg:col-span-1 space-y-4">
            <div className="glass-card p-4 space-y-3">
              <div className="flex items-center justify-between">
                <h3 className="font-bold text-sm text-foreground flex items-center gap-2">
                  <FileText className="w-4 h-4 text-primary" />
                  Bulletins Feed
                </h3>
                <span className="text-xs text-muted-foreground">{filteredBulletins.length} available</span>
              </div>

              {/* Search */}
              <div className="relative">
                <Search className="w-3.5 h-3.5 absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground" />
                <input
                  type="text"
                  placeholder="Search bulletin text..."
                  value={searchQuery}
                  onChange={(e) => setSearchQuery(e.target.value)}
                  className="w-full pl-8 pr-3 py-1.5 bg-secondary/50 border border-border rounded-lg text-xs text-foreground placeholder:text-muted-foreground focus:outline-none focus:ring-1 focus:ring-primary"
                />
              </div>

              {/* Warning Level Filters */}
              <div className="flex gap-1.5 flex-wrap">
                {["ALL", "RED", "ORANGE", "YELLOW"].map((lvl) => (
                  <button
                    key={lvl}
                    onClick={() => setFilterLevel(lvl)}
                    className={`px-2.5 py-1 rounded text-xs font-bold transition-all ${
                      filterLevel === lvl
                        ? "bg-primary text-primary-foreground shadow-sm"
                        : "bg-secondary/60 text-muted-foreground hover:text-foreground"
                    }`}
                  >
                    {lvl}
                  </button>
                ))}
              </div>
            </div>

            {/* List of Bulletins */}
            <div className="space-y-2.5 max-h-[600px] overflow-y-auto pr-1">
              {filteredBulletins.map((b) => (
                <div
                  key={b.id}
                  onClick={() => setSelectedBulletin(b)}
                  className={`p-4 rounded-xl border transition-all cursor-pointer ${
                    selectedBulletin?.id === b.id
                      ? "bg-primary/10 border-primary shadow-md ring-1 ring-primary/30"
                      : "bg-secondary/20 hover:bg-secondary/40 border-border"
                  }`}
                >
                  <div className="flex items-center justify-between mb-1.5">
                    <span className="font-bold text-sm text-foreground">Bulletin #{b.number}</span>
                    {b.is_latest && (
                      <span className="px-2 py-0.5 rounded text-[10px] font-black uppercase bg-primary text-primary-foreground tracking-wider animate-pulse">
                        Latest
                      </span>
                    )}
                  </div>
                  <p className="text-xs text-muted-foreground line-clamp-1">{b.category} • {b.intensity_knots ?? "Not available"} kts</p>
                  <div className="flex items-center justify-between text-[11px] text-muted-foreground mt-2 pt-2 border-t border-border/40 font-mono">
                    <span>{b.timestamp_ist}</span>
                    <span className={`font-bold ${b.alert_level === "RED" ? "text-red-400" : "text-orange-400"}`}>
                      {b.alert_level}
                    </span>
                  </div>
                </div>
              ))}
            </div>
          </div>

          {/* Full Bulletin Previewer */}
          <div className="lg:col-span-2 space-y-4">
            {selectedBulletin ? (
              <div className="glass-card p-6 border-border space-y-5">
                {/* Bulletin Header */}
                <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 border-b border-border/80 pb-4">
                  <div>
                    <div className="flex items-center gap-2">
                      <span className="text-xs font-mono font-bold text-primary">BULLETIN RECORD</span>
                      <span className="px-2 py-0.5 rounded text-[10px] font-bold bg-secondary text-foreground">
                        {selectedBulletin.id}
                      </span>
                    </div>
                    <h2 className="text-xl font-bold text-foreground mt-1">{selectedBulletin.title}</h2>
                    <p className="text-xs text-muted-foreground font-mono mt-0.5">
                      Issued: {selectedBulletin.timestamp_utc ?? "Not available"} ({selectedBulletin.timestamp_ist ?? "Not available"})
                    </p>
                  </div>

                  <div className="flex items-center gap-2">
                    <button
                      onClick={() => handleCopyBulletin(selectedBulletin.full_text)}
                      className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-secondary/80 hover:bg-secondary border border-border text-xs font-medium text-foreground transition-colors"
                    >
                      <Copy className="w-3.5 h-3.5" /> Copy
                    </button>
                    <button
                      onClick={handleDownloadPdf}
                      disabled={pdfLoading}
                      aria-busy={pdfLoading}
                      title="Download Cyclone Meteorological PDF Advisory (Exercise Simulation)"
                      className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-primary text-primary-foreground hover:bg-primary/90 text-xs font-medium transition-colors cursor-pointer"
                    >
                      <Download className="w-3.5 h-3.5" /> {pdfLoading ? "Preparing PDF…" : "Download PDF"}
                    </button>
                  </div>
                </div>

                {/* Key Metrics Strip */}
                <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
                  <div className="p-3 rounded-lg bg-secondary/40 border border-border">
                    <p className="text-[10px] uppercase font-semibold text-muted-foreground">Wind Speed ({sourceBadge.shortLabel})</p>
                    <p className="text-lg font-mono font-bold text-foreground">{getConvertedKnots(selectedBulletin.intensity_knots)} kts</p>
                    <p className="text-xs text-muted-foreground">{getConvertedKmh(selectedBulletin.intensity_knots)} km/h</p>
                  </div>
                  <div className="p-3 rounded-lg bg-secondary/40 border border-border">
                    <p className="text-[10px] uppercase font-semibold text-muted-foreground">Peak Gusts</p>
                    <p className="text-lg font-mono font-bold text-orange-400">{selectedBulletin.gusts_kmh ?? "Not available"} km/h</p>
                    <p className="text-xs text-muted-foreground">Gale force</p>
                  </div>
                  <div className="p-3 rounded-lg bg-secondary/40 border border-border">
                    <p className="text-[10px] uppercase font-semibold text-muted-foreground">Storm Surge</p>
                    <p className="text-lg font-mono font-bold text-cyan-400">{selectedBulletin.storm_surge_meters} m</p>
                    <p className="text-xs text-muted-foreground">Above tide</p>
                  </div>
                  <div className="p-3 rounded-lg bg-secondary/40 border border-border">
                    <p className="text-[10px] uppercase font-semibold text-muted-foreground">Central Pressure</p>
                    <p className="text-lg font-mono font-bold text-foreground">{selectedBulletin.central_pressure_hpa ?? "Not available"} hPa</p>
                    <p className="text-xs text-muted-foreground">Estimated</p>
                  </div>
                </div>

                {/* Experimental Analysis Text View */}
                <div className="p-5 rounded-xl bg-zinc-950/80 border border-border font-mono text-xs text-zinc-200 leading-relaxed whitespace-pre-wrap select-text shadow-inner max-h-[450px] overflow-y-auto">
                  {selectedBulletin.full_text}
                </div>
              </div>
            ) : (
              <div className="glass-card p-12 text-center text-muted-foreground">
                <FileText className="w-10 h-10 mx-auto opacity-30 mb-2" />
                <p>Select a bulletin from the left panel to inspect full technical text.</p>
              </div>
            )}
          </div>
        </div>
      )}

      {/* ══════════════════════════════════════════════════════════════════════
          TAB 5: LOCAL EXERCISE TEMPLATES
         ══════════════════════════════════════════════════════════════════════ */}
      {activeTab === "broadcast" && (
        <div className="space-y-6 animate-in fade-in duration-300">
          {/* Broadcast Status Tiles */}
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
            <div className="glass-card p-5 border-border space-y-2">
              <div className="flex items-center justify-between">
                <span className="p-2 rounded-lg bg-emerald-500/10 text-emerald-400"><PhoneCall className="w-4 h-4" /></span>
                <span className="text-[11px] font-bold text-amber-400 bg-amber-500/10 px-2 py-0.5 rounded">SIMULATED DRILL</span>
              </div>
              <p className="text-xs text-muted-foreground">Cell Broadcast & SMS Pipeline</p>
              <p className="text-xl font-mono font-bold text-foreground">No delivery adapter</p>
              <p className="text-[11px] text-muted-foreground">Live Delivery: NOT_APPLICABLE</p>
            </div>

            <div className="glass-card p-5 border-border space-y-2">
              <div className="flex items-center justify-between">
                <span className="p-2 rounded-lg bg-red-500/10 text-red-400"><Siren className="w-4 h-4" /></span>
                <span className="text-[11px] font-bold text-amber-400 bg-amber-500/10 px-2 py-0.5 rounded">SIMULATED DRILL</span>
              </div>
              <p className="text-xs text-muted-foreground">Coastal Acoustic Sirens</p>
              <p className="text-xl font-mono font-bold text-foreground">No hardware connection</p>
              <p className="text-[11px] text-muted-foreground">Live Delivery: NOT_APPLICABLE</p>
            </div>

            <div className="glass-card p-5 border-border space-y-2">
              <div className="flex items-center justify-between">
                <span className="p-2 rounded-lg bg-blue-500/10 text-blue-400"><Radio className="w-4 h-4" /></span>
                <span className="text-[11px] font-bold text-blue-400 bg-blue-500/10 px-2 py-0.5 rounded">DRAFT ONLY</span>
              </div>
              <p className="text-xs text-muted-foreground">Radio exercise template</p>
              <p className="text-xl font-mono font-bold text-foreground">No hardware connection</p>
              <p className="text-[11px] text-muted-foreground">Live Delivery: NOT_APPLICABLE</p>
            </div>

            <div className="glass-card p-5 border-border space-y-2">
              <div className="flex items-center justify-between">
                <span className="p-2 rounded-lg bg-amber-500/10 text-amber-400"><ShieldCheck className="w-4 h-4" /></span>
                <span className="text-[11px] font-bold text-amber-400 bg-amber-500/10 px-2 py-0.5 rounded">SIMULATED DRILL</span>
              </div>
              <p className="text-xs text-muted-foreground">Official agency resources</p>
              <p className="text-xl font-mono font-bold text-foreground">OASIS CAP v1.2</p>
              <p className="text-[11px] text-muted-foreground">Live Delivery: NOT_APPLICABLE</p>
            </div>
          </div>

          {/* Interactive Broadcast Dispatch Tool */}
          <div className="glass-card p-6 border-border space-y-5">
            <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-2 border-b border-border/80 pb-4">
              <div>
                <h3 className="text-lg font-bold text-foreground flex items-center gap-2">
                  <Send className="w-4 h-4 text-primary" />
                  Local exercise draft generator
                </h3>
                <p className="text-xs text-muted-foreground mt-0.5">
                  Test and verify emergency alert propagation across multi-channel public warning infrastructure.
                </p>
              </div>
              <span className="text-xs font-mono text-muted-foreground bg-secondary px-2.5 py-1 rounded">
                Protocol: OASIS-CAP-1.2-IN
              </span>
            </div>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {/* Configuration Controls */}
              <div className="space-y-4">
                <div>
                  <label className="text-xs font-semibold text-foreground uppercase tracking-wider block mb-1.5">
                    Alert Directive Type
                  </label>
                  <select
                    value={alertType}
                    onChange={(e) => setAlertType(e.target.value)}
                    disabled={dispatchStatus === "dispatching"}
                    className="w-full px-3 py-2 bg-secondary/80 border border-border rounded-lg text-xs font-semibold text-foreground focus:outline-none focus:ring-1 focus:ring-primary"
                  >
                    <option value="EVACUATION_WARNING">RED ALERT: Coastal Hazard Advisory Simulation (Exercise Only)</option>
                    <option value="STORM_SURGE_EMERGENCY">ORANGE ALERT: Storm Surge & Inundation Warning</option>
                    <option value="FISHERMEN_RECALL">YELLOW ALERT: Marine Return & Total Sea Suspension</option>
                    <option value="ALL_CLEAR">ALL CLEAR: Threat Passed / Return Safe</option>
                  </select>
                </div>

                <div>
                  <label className="text-xs font-semibold text-foreground uppercase tracking-wider block mb-1.5">
                    Transmission Channels
                  </label>
                  <div className="grid grid-cols-2 gap-2">
                    {[
                      { id: "sms", label: "Cell Broadcast & SMS" },
                      { id: "siren", label: "Acoustic Sirens" },
                      { id: "vhf", label: "Marine VHF / Navtex" },
                      { id: "sachet", label: "Exercise notification template" },
                    ].map((ch) => (
                      <button
                        key={ch.id}
                        type="button"
                        onClick={() => toggleChannel(ch.id)}
                        disabled={dispatchStatus === "dispatching"}
                        className={`p-2.5 rounded-lg border text-left text-xs font-medium transition-all ${
                          selectedChannels.includes(ch.id)
                            ? "bg-primary/15 border-primary/50 text-foreground ring-1 ring-primary/20"
                            : "bg-secondary/40 border-border text-muted-foreground"
                        }`}
                      >
                        <div className="flex items-center gap-2">
                          <span className={`w-2 h-2 rounded-full ${selectedChannels.includes(ch.id) ? "bg-primary" : "bg-muted-foreground"}`} />
                          {ch.label}
                        </div>
                      </button>
                    ))}
                  </div>
                </div>

                <div>
                  <label className="text-xs font-semibold text-foreground uppercase tracking-wider block mb-1.5">
                    Targeted Coastal Districts ({affectedDistricts.length})
                  </label>
                  <div className="flex flex-wrap gap-1.5 max-h-24 overflow-y-auto p-2 rounded-lg bg-secondary/20 border border-border">
                    {affectedDistricts.map((d, i) => (
                      <span key={i} className="px-2 py-0.5 rounded text-[11px] font-mono bg-secondary text-foreground">
                        {d.district}
                      </span>
                    ))}
                  </div>
                </div>

                <button
                  onClick={handleDispatchSimulation}
                  disabled={dispatchStatus === "dispatching"}
                  className="w-full py-3 bg-red-600 hover:bg-red-500 disabled:opacity-50 text-white font-bold rounded-xl text-xs uppercase tracking-wider shadow-lg shadow-red-600/30 transition-all flex items-center justify-center gap-2 cursor-pointer"
                >
                  {dispatchStatus === "dispatching" ? (
                    <>
                      <RefreshCw className="w-4 h-4 animate-spin" /> Dispatching Broadcast Pipeline...
                    </>
                  ) : (
                    <>
                      <Radio className="w-4 h-4 animate-pulse" /> Dispatch Multi-Channel Emergency Alert
                    </>
                  )}
                </button>
              </div>

              {/* Live Pipeline Animation & Receipt */}
              <div className="p-5 rounded-xl bg-zinc-950/80 border border-border flex flex-col justify-between space-y-4">
                <div className="space-y-3">
                  <p className="text-xs font-mono font-bold text-primary uppercase">Broadcast Pipeline Telemetry</p>
                  
                  <div className="space-y-2 text-xs font-mono">
                    <div className={`p-2 rounded flex items-center gap-2 ${dispatchStep >= 1 ? "bg-emerald-500/10 text-emerald-400 border border-emerald-500/20" : "text-muted-foreground"}`}>
                      {dispatchStep >= 1 ? <CheckCircle2 className="w-3.5 h-3.5 shrink-0" /> : <div className="w-3.5 h-3.5 rounded-full border border-current shrink-0" />}
                      <span>1. OASIS CAP-CP v1.2 XML Payload Encoded</span>
                    </div>

                    <div className={`p-2 rounded flex items-center gap-2 ${dispatchStep >= 2 ? "bg-emerald-500/10 text-emerald-400 border border-emerald-500/20" : "text-muted-foreground"}`}>
                      {dispatchStep >= 2 ? <CheckCircle2 className="w-3.5 h-3.5 shrink-0" /> : <div className="w-3.5 h-3.5 rounded-full border border-current shrink-0" />}
                      <span>2. Cellular Tower Gateway Handshake (14 Marine Corridors)</span>
                    </div>

                    <div className={`p-2 rounded flex items-center gap-2 ${dispatchStep >= 3 ? "bg-emerald-500/10 text-emerald-400 border border-emerald-500/20" : "text-muted-foreground"}`}>
                      {dispatchStep >= 3 ? <CheckCircle2 className="w-3.5 h-3.5 shrink-0" /> : <div className="w-3.5 h-3.5 rounded-full border border-current shrink-0" />}
                      <span>3. Coastal Acoustic Siren Trigger Synchronized</span>
                    </div>

                    <div className={`p-2 rounded flex items-center gap-2 ${dispatchStep >= 4 ? "bg-emerald-500/10 text-emerald-400 border border-emerald-500/20" : "text-muted-foreground"}`}>
                      {dispatchStep >= 4 ? <CheckCircle2 className="w-3.5 h-3.5 shrink-0" /> : <div className="w-3.5 h-3.5 rounded-full border border-current shrink-0" />}
                      <span>4. Final Delivery Confirmation & Acknowledgement Logged</span>
                    </div>
                  </div>
                </div>

                {dispatchReceipt && (
                  <div className="p-3 rounded-lg bg-emerald-500/10 border border-emerald-500/30 text-emerald-300 text-xs space-y-1 font-mono">
                    <p className="font-bold flex items-center gap-1.5 text-emerald-400">
                      <CheckCircle2 className="w-3.5 h-3.5" /> Dispatch Receipt: {dispatchReceipt.dispatch_id}
                    </p>
                    <p className="text-[11px] text-muted-foreground">
                      Time: {dispatchReceipt.timestamp}
                    </p>
                    <p className="text-[11px] text-muted-foreground line-clamp-2">
                      Payload: &quot;{dispatchReceipt.message_payload}&quot;
                    </p>
                  </div>
                )}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

"use client";

import React, { useState, useRef, useEffect } from "react";
import { motion, AnimatePresence, useReducedMotion } from "framer-motion";
import { 
  X, 
  Send, 
  Minimize2, 
  Maximize2, 
  RotateCcw, 
  Sparkles, 
  Cloud,
  Satellite,
  BarChart3,
  ShieldCheck,
  ChevronRight,
  Mic,
  MicOff,
  MoreHorizontal,
  Copy, 
  Check, 
  GripHorizontal
} from "lucide-react";
import { useLiquidGlass } from "@/hooks/useLiquidGlass";
import { CycloneLogo } from "@/components/CycloneLogo";
import { API_BASE_URL, getApiBaseUrl } from "@/lib/api";
import { readChatReply } from "@/lib/chatResponse";

interface Message {
  id: string;
  role: "user" | "assistant";
  content: string;
  category?: string;
  sources?: string[];
  timestamp: string;
}

const FEATURE_CARDS = [
  {
    title: "Current source status",
    desc: "Check availability and uncertainty",
    icon: Sparkles,
    color: "blue",
    iconBg: "bg-blue-500/20 text-blue-400 border-blue-500/30",
    query: "What is the current backend source status?"
  },
  {
    title: "Hydrodynamic Storm Surge",
    desc: "Parametric physics & compound flooding",
    icon: Cloud,
    color: "cyan",
    iconBg: "bg-cyan-500/20 text-cyan-400 border-cyan-500/30",
    query: "Explain the hydrodynamic physics of storm surge in the Bay of Bengal: how the inverted barometer effect, shallow shelf bathymetry, and astronomical high tide combine to cause coastal inundation."
  },
  {
    title: "Dvorak concepts",
    desc: "Learn the limits of image interpretation",
    icon: Satellite,
    color: "rose",
    iconBg: "bg-rose-500/20 text-rose-400 border-rose-500/30",
    query: "Explain the Dvorak technique and why image classification is not a calibrated wind measurement."
  },
  {
    title: "Cyclone formation",
    desc: "Explore general meteorology",
    icon: ShieldCheck,
    color: "emerald",
    iconBg: "bg-emerald-500/20 text-emerald-400 border-emerald-500/30",
    query: "Explain cyclogenesis."
  }
];


function fitDimension(value: number, minimum: number, available: number) {
  return Math.min(Math.max(1, available), Math.max(minimum, Number.isFinite(value) ? value : minimum));
}

export function ChatbotWidget() {
  const reduceMotion = useReducedMotion();
  const openerRef = useRef<HTMLElement | null>(null);
  const [isOpen, setIsOpen] = useState(false);
  const [isMinimized, setIsMinimized] = useState(false);
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);
  const [copiedId, setCopiedId] = useState<string | null>(null);
  const [screenContext, setScreenContext] = useState<Record<string, unknown> | null>(null);
  const [messages, setMessages] = useState<Message[]>([]);
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isListening, setIsListening] = useState(false);
  const recognitionRef = useRef<CycloneSpeechRecognition | null>(null);
  const pendingRequest = useRef<AbortController | null>(null);

  useEffect(() => () => {
    pendingRequest.current?.abort();
    pendingRequest.current = null;
    recognitionRef.current?.stop();
  }, []);

  const toggleVoiceInput = () => {
    if (typeof window === "undefined") return;

    const SpeechRecognition =
      window.SpeechRecognition || window.webkitSpeechRecognition;

    if (!SpeechRecognition) {
      alert("Voice input is not supported in this browser. Please use Chrome or Edge.");
      return;
    }

    if (isListening) {
      recognitionRef.current?.stop();
      setIsListening(false);
      return;
    }

    try {
      const recognition = new SpeechRecognition();
      recognition.continuous = false;
      recognition.interimResults = true;
      recognition.lang = "en-US";

      recognition.onstart = () => {
        setIsListening(true);
      };

      recognition.onresult = (event) => {
        const transcript = Array.from(event.results)
          .map((result) => result[0].transcript)
          .join("");
        setInput(transcript);
      };

      recognition.onerror = (event) => {
        console.warn("Speech recognition error:", event.error);
        setIsListening(false);
      };

      recognition.onend = () => {
        setIsListening(false);
      };

      recognitionRef.current = recognition;
      recognition.start();
    } catch (err) {
      console.warn("Error starting speech recognition:", err);
      setIsListening(false);
    }
  };

  // Sync live UI telemetry from window.__cyclonet_current_context
  useEffect(() => {
    if (!isOpen) return;
    const updateContext = () => {
      if (typeof window !== "undefined") {
        setScreenContext(window.__cyclonet_current_context || null);
      }
    };
    updateContext();
    const interval = setInterval(updateContext, 1000);
    return () => clearInterval(interval);
  }, [isOpen]);

  // Liquid Glass Background hook from nebula-map
  const glassRef = useLiquidGlass<HTMLDivElement>(isOpen);

  // Draggable position & resizable size state
  const [hasMounted, setHasMounted] = useState(false);
  const [pos, setPos] = useState<{ x: number; y: number }>({ x: 0, y: 0 });
  const [size, setSize] = useState<{ width: number; height: number }>({ width: 520, height: 740 });
  const [isDragging, setIsDragging] = useState(false);
  const [isResizing, setIsResizing] = useState(false);
  const [dragOffset, setDragOffset] = useState({ x: 0, y: 0 });
  const [resizeStart, setResizeStart] = useState({ clientX: 0, clientY: 0, width: 520, height: 740 });

  const SAFE_MARGIN = 16;

  // Initialize position & size on client mount
  useEffect(() => {
    const frame = requestAnimationFrame(() => {
    setHasMounted(true);
    if (typeof window !== "undefined") {
      let initialWidth = Math.min(520, window.innerWidth - 32);
      let initialHeight = Math.min(740, window.innerHeight - 60);
      const savedSize = localStorage.getItem("cyclonet_chat_size_v4");
      if (savedSize) {
        try {
          const parsed = JSON.parse(savedSize);
          if (typeof parsed.width === "number" && typeof parsed.height === "number") {
            initialWidth = fitDimension(parsed.width, 380, window.innerWidth - 32);
            initialHeight = fitDimension(parsed.height, 400, window.innerHeight - 60);
          }
        } catch (_) {}
      }
      setSize({ width: initialWidth, height: initialHeight });

      const savedPos = localStorage.getItem("cyclonet_chat_pos_v4");
      if (savedPos) {
        try {
          const parsed = JSON.parse(savedPos);
          if (typeof parsed.x === "number" && typeof parsed.y === "number") {
            const maxX = Math.max(SAFE_MARGIN, window.innerWidth - initialWidth - SAFE_MARGIN);
            const maxY = Math.max(SAFE_MARGIN, window.innerHeight - initialHeight - SAFE_MARGIN);
            setPos({
              x: Math.max(SAFE_MARGIN, Math.min(parsed.x, maxX)),
              y: Math.max(SAFE_MARGIN, Math.min(parsed.y, maxY))
            });
            return;
          }
        } catch (_) {}
      }
      setPos({
        x: Math.max(SAFE_MARGIN, window.innerWidth - initialWidth - 24),
        y: Math.max(SAFE_MARGIN, window.innerHeight - initialHeight - 60)
      });
    }
    });
    return () => cancelAnimationFrame(frame);
  }, []);

  useEffect(() => {
    if (hasMounted && typeof window !== "undefined") {
      localStorage.setItem("cyclonet_chat_pos_v4", JSON.stringify(pos));
    }
  }, [pos, hasMounted]);

  useEffect(() => {
    if (hasMounted && typeof window !== "undefined") {
      localStorage.setItem("cyclonet_chat_size_v4", JSON.stringify(size));
    }
  }, [size, hasMounted]);

  // Listen for external open trigger
  useEffect(() => {
    const handleExternalOpen = () => {
      openerRef.current = document.activeElement instanceof HTMLElement ? document.activeElement : null;
      setIsOpen(true);
      setIsMinimized(false);
    };
    window.addEventListener("cyclonet:open-chat", handleExternalOpen);
    return () => window.removeEventListener("cyclonet:open-chat", handleExternalOpen);
  }, []);

  // Handle window resizing
  useEffect(() => {
    const handleResize = () => {
      if (typeof window === "undefined") return;
      const width = fitDimension(size.width, 380, window.innerWidth - SAFE_MARGIN * 2);
      const height = fitDimension(size.height, 400, window.innerHeight - SAFE_MARGIN * 2);
      setSize({ width, height });
      const currentHeight = isMinimized ? 64 : height;
      const maxX = Math.max(SAFE_MARGIN, window.innerWidth - width - SAFE_MARGIN);
      const maxY = Math.max(SAFE_MARGIN, window.innerHeight - currentHeight - SAFE_MARGIN);
      setPos(prev => ({
        x: Math.max(SAFE_MARGIN, Math.min(prev.x, maxX)),
        y: Math.max(SAFE_MARGIN, Math.min(prev.y, maxY))
      }));
    };

    window.addEventListener("resize", handleResize);
    return () => window.removeEventListener("resize", handleResize);
  }, [size.width, size.height, isMinimized]);

  // Dragging event listeners
  const handleDragStart = (e: React.MouseEvent | React.TouchEvent) => {
    if ("button" in e && e.button !== 0) return;
    const target = e.target as HTMLElement;
    if (target.closest("button, textarea, input, a, [role='button']")) return;

    const clientX = "touches" in e ? e.touches[0].clientX : e.clientX;
    const clientY = "touches" in e ? e.touches[0].clientY : e.clientY;

    setIsDragging(true);
    setDragOffset({
      x: clientX - pos.x,
      y: clientY - pos.y
    });
  };

  const handleResizeStart = (e: React.MouseEvent | React.TouchEvent) => {
    e.stopPropagation();
    e.preventDefault();
    const clientX = "touches" in e ? e.touches[0].clientX : e.clientX;
    const clientY = "touches" in e ? e.touches[0].clientY : e.clientY;

    setIsResizing(true);
    setResizeStart({
      clientX,
      clientY,
      width: size.width,
      height: size.height
    });
  };

  useEffect(() => {
    if (!isDragging && !isResizing) return;

    const handleMouseMove = (e: MouseEvent) => {
      if (isDragging) {
        const currentHeight = isMinimized ? 56 : size.height;
        const maxX = Math.max(SAFE_MARGIN, window.innerWidth - size.width - SAFE_MARGIN);
        const maxY = Math.max(SAFE_MARGIN, window.innerHeight - currentHeight - SAFE_MARGIN);

        const nextX = Math.max(SAFE_MARGIN, Math.min(e.clientX - dragOffset.x, maxX));
        const nextY = Math.max(SAFE_MARGIN, Math.min(e.clientY - dragOffset.y, maxY));
        setPos({ x: nextX, y: nextY });
      } else if (isResizing) {
        const deltaX = e.clientX - resizeStart.clientX;
        const deltaY = e.clientY - resizeStart.clientY;
        const maxAllowedW = window.innerWidth - pos.x - SAFE_MARGIN;
        const maxAllowedH = window.innerHeight - pos.y - SAFE_MARGIN;

        const newW = fitDimension(resizeStart.width + deltaX, 380, maxAllowedW);
        const newH = fitDimension(resizeStart.height + deltaY, 400, maxAllowedH);
        setSize({ width: newW, height: newH });
      }
    };

    const handleTouchMove = (e: TouchEvent) => {
      if (!e.touches[0]) return;
      if (isDragging) {
        const currentHeight = isMinimized ? 56 : size.height;
        const maxX = Math.max(SAFE_MARGIN, window.innerWidth - size.width - SAFE_MARGIN);
        const maxY = Math.max(SAFE_MARGIN, window.innerHeight - currentHeight - SAFE_MARGIN);

        const nextX = Math.max(SAFE_MARGIN, Math.min(e.touches[0].clientX - dragOffset.x, maxX));
        const nextY = Math.max(SAFE_MARGIN, Math.min(e.touches[0].clientY - dragOffset.y, maxY));
        setPos({ x: nextX, y: nextY });
      } else if (isResizing) {
        const deltaX = e.touches[0].clientX - resizeStart.clientX;
        const deltaY = e.touches[0].clientY - resizeStart.clientY;
        const maxAllowedW = window.innerWidth - pos.x - SAFE_MARGIN;
        const maxAllowedH = window.innerHeight - pos.y - SAFE_MARGIN;

        const newW = fitDimension(resizeStart.width + deltaX, 380, maxAllowedW);
        const newH = fitDimension(resizeStart.height + deltaY, 400, maxAllowedH);
        setSize({ width: newW, height: newH });
      }
    };

    const handleEnd = () => {
      setIsDragging(false);
      setIsResizing(false);
    };

    window.addEventListener("mousemove", handleMouseMove);
    window.addEventListener("mouseup", handleEnd);
    window.addEventListener("touchmove", handleTouchMove, { passive: false });
    window.addEventListener("touchend", handleEnd);

    return () => {
      window.removeEventListener("mousemove", handleMouseMove);
      window.removeEventListener("mouseup", handleEnd);
      window.removeEventListener("touchmove", handleTouchMove);
      window.removeEventListener("touchend", handleEnd);
    };
  }, [isDragging, isResizing, dragOffset, resizeStart, size.width, size.height, isMinimized, pos.x, pos.y]);

  const messagesEndRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (!isOpen || isMinimized || !hasMounted) return;
    const frame = requestAnimationFrame(() => inputRef.current?.focus());
    return () => cancelAnimationFrame(frame);
  }, [isOpen, isMinimized, hasMounted]);

  const closeAssistant = () => {
    setIsOpen(false);
    setIsMenuOpen(false);
    recognitionRef.current?.stop();
    setIsListening(false);
    openerRef.current?.focus();
  };

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: reduceMotion ? "instant" : "smooth" });
  };

  useEffect(() => {
    if (isOpen && !isMinimized && messages.length > 0) {
      scrollToBottom();
    }
  }, [messages, isOpen, isMinimized, loading]);

  const handleSend = async (textToSend?: string) => {
    const text = (textToSend || input).trim();
    if (!text || pendingRequest.current) return;
    const controller = new AbortController();
    pendingRequest.current = controller;

    const userMessage: Message = {
      id: crypto.randomUUID(),
      role: "user",
      content: text,
      timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
    };

    setMessages(prev => [...prev, userMessage]);
    if (!textToSend) setInput("");
    setLoading(true);

    try {
      const historyPayload = messages
        .slice(-6)
        .map(m => ({ role: m.role, content: m.content.slice(0,2000) }));
      
      let uiContext: Record<string, unknown> | null = null;
      if (typeof window !== "undefined") {
        uiContext = {page:window.location.pathname.slice(0,80)};
      }

      const res = await fetch(`${getApiBaseUrl()}/api/chat`, {
        method: "POST",
        signal: AbortSignal.any([controller.signal, AbortSignal.timeout(65000)]),
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          message: text,
          history: historyPayload,
          ui_context: uiContext
        })
      });

      if (!res.ok) {
        throw new Error(`Server returned ${res.status}`);
      }

      const data = await readChatReply(res);
      if (pendingRequest.current !== controller) return;
      const assistantMessage: Message = {
        id: crypto.randomUUID(),
        role: "assistant",
        content: data.response || "No response received.",
        category: data.category,
        sources: data.sources,
        timestamp: data.timestamp || new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
      };
      setMessages(prev => [...prev, assistantMessage]);
    } catch (err: unknown) {
      if (pendingRequest.current !== controller) return;
      setMessages(prev => [
        ...prev,
        {
          id: crypto.randomUUID(),
          role: "assistant",
          content: "Source information is unavailable. Try again shortly; no current conditions or safety assessment can be established.",
          category: "error",
          timestamp: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
        }
      ]);
    } finally {
      if (pendingRequest.current === controller) {
        pendingRequest.current = null;
        setLoading(false);
      }
    }
  };

  const handleCopy = (text: string, id: string) => {
    navigator.clipboard.writeText(text);
    setCopiedId(id);
    setTimeout(() => setCopiedId(null), 2000);
  };

  const handleClear = () => {
    pendingRequest.current?.abort();
    pendingRequest.current = null;
    setLoading(false);
    setMessages([]);
    setCopiedId(null);
    setIsMenuOpen(false);
  };

  const formatContent = (text: string, isUser: boolean = false) => {
    return text.split("\n").map((line, idx) => {
      if (line.startsWith("### ")) {
        return (
          <h4 key={idx} className={`font-heading font-bold text-sm mt-3 mb-1.5 flex items-center gap-1.5 ${isUser ? "text-zinc-950 font-black" : "text-white"}`}>
            {line.replace("### ", "")}
          </h4>
        );
      }
      if (line.startsWith("#### ")) {
        return (
          <h5 key={idx} className={`font-semibold text-xs mt-2 mb-1 ${isUser ? "text-zinc-900 font-bold" : "text-zinc-200"}`}>
            {line.replace("#### ", "")}
          </h5>
        );
      }
      if (line.trim().startsWith("- ") || line.trim().startsWith("* ")) {
        const bulletText = line.trim().substring(2);
        return (
          <div key={idx} className={`flex items-start gap-2 ml-1 my-1 text-xs leading-relaxed ${isUser ? "text-zinc-950 font-medium" : "text-zinc-300"}`}>
            <span className={isUser ? "text-zinc-900 mt-1 text-[8px]" : "text-zinc-400 mt-1 text-[8px]"}>•</span>
            <span>{renderFormattedInline(bulletText, isUser)}</span>
          </div>
        );
      }
      if (/^\d+\.\s/.test(line.trim())) {
        const match = line.trim().match(/^(\d+\.)\s(.*)$/);
        if (match) {
          return (
            <div key={idx} className={`flex items-start gap-2 ml-1 my-1 text-xs leading-relaxed ${isUser ? "text-zinc-950 font-medium" : "text-zinc-300"}`}>
              <span className={`font-mono text-xs ${isUser ? "text-zinc-900 font-bold" : "text-zinc-400"}`}>{match[1]}</span>
              <span>{renderFormattedInline(match[2], isUser)}</span>
            </div>
          );
        }
      }
      if (line.trim().startsWith("|---")) {
        return null;
      }
      if (line.trim().startsWith("|") && line.trim().endsWith("|")) {
        const cells = line.split("|").filter((_, i, arr) => i > 0 && i < arr.length - 1);
        return (
          <div key={idx} className={`grid grid-cols-4 gap-1 py-1 px-1.5 text-[11px] border-b border-border/40 font-mono ${isUser ? "text-zinc-950" : ""}`}>
            {cells.map((cell, cIdx) => (
              <span key={cIdx} className={cIdx === 0 ? (isUser ? "font-bold text-zinc-950" : "font-semibold text-white") : (isUser ? "text-zinc-850 truncate" : "text-zinc-400 truncate")}>
                {cell.trim().replace(/\$/g, "")}
              </span>
            ))}
          </div>
        );
      }
      if (!line.trim()) {
        return <div key={idx} className="h-1.5" />;
      }
      return (
        <p key={idx} className={`text-xs my-1 leading-relaxed ${isUser ? "text-zinc-950 font-semibold" : "text-zinc-200"}`}>
          {renderFormattedInline(line, isUser)}
        </p>
      );
    });
  };

  const renderFormattedInline = (str: string, isUser: boolean = false) => {
    const parts = str.split(/(\*\*.*?\*\*)/g);
    return parts.map((part, pIdx) => {
      if (part.startsWith("**") && part.endsWith("**")) {
        return <strong key={pIdx} className={isUser ? "font-bold text-zinc-950" : "font-semibold text-white"}>{part.slice(2, -2)}</strong>;
      }
      const codeParts = part.split(/(`.*?`)/g);
      return codeParts.map((sub, sIdx) => {
        if (sub.startsWith("`") && sub.endsWith("`")) {
          return (
            <code key={sIdx} className={`px-1 py-0.5 rounded font-mono text-[11px] ${isUser ? "bg-zinc-200 text-zinc-950 font-bold" : "bg-white/10 text-zinc-100"}`}>
              {sub.slice(1, -1)}
            </code>
          );
        }
        return sub;
      });
    });
  };

  return (
    <>
      {/* Floating Chat Window with Liquid Glass, Dragging and Resizing */}
      <AnimatePresence>
        {isOpen && hasMounted && (
          <motion.div
            ref={glassRef}
            role="dialog"
            aria-label="CycloNet AI assistant"
            aria-modal="false"
            onKeyDown={(event) => {
              if (event.key !== "Escape") return;
              event.preventDefault();
              event.stopPropagation();
              if (isMenuOpen) setIsMenuOpen(false);
              else closeAssistant();
            }}
            initial={{ opacity: 0, scale: 0.9, y: 15 }}
            animate={{ opacity: 1, scale: 1, y: 0 }}
            exit={{ opacity: 0, scale: 0.9, y: 15 }}
            transition={reduceMotion ? { duration: 0 } : { type: "spring", stiffness: 350, damping: 26 }}
            style={{
              position: "fixed",
              left: `${pos.x}px`,
              top: `${pos.y}px`,
              width: `${size.width}px`,
              height: isMinimized ? "64px" : `${size.height}px`,
              zIndex: 9999,
              touchAction: (isDragging || isResizing) ? "none" : "auto",
              cursor: isDragging ? "grabbing" : isResizing ? "nwse-resize" : "default",
              userSelect: (isDragging || isResizing) ? "none" : "auto",
              boxShadow: (isDragging || isResizing)
                ? "0 30px 70px rgba(0,0,0,0.7), 0 0 30px rgba(59,130,246,0.2)" 
                : undefined
            }}
            className="liquid-glass-panel flex flex-col rounded-[26px] overflow-hidden transition-[box-shadow,height] duration-200 relative border border-white/15"
          >
            {/* Header: educational assistant */}
            <div 
              onMouseDown={handleDragStart}
              onTouchStart={handleDragStart}
              className="chat-drag-handle p-3.5 px-5 bg-zinc-950/50 border-b border-white/10 flex items-center justify-between relative select-none shrink-0"
              title="Click and drag to move chat window"
            >
              <div className="flex items-center gap-3 pointer-events-none select-none">
                <div className="relative">
                  <CycloneLogo size={32} />
                </div>
                <div>
                  <h3 className="font-heading font-bold text-sm text-white tracking-tight flex items-center gap-1.5">
                    <span>CycloNet AI</span>
                    <span className="px-1.5 py-0.2 rounded text-[9px] font-mono font-bold bg-primary/20 text-primary border border-primary/30">Research</span>
                  </h3>
                  <p className="text-[11px] text-zinc-400">
                    Education and source status
                  </p>
                </div>
              </div>

              {/* Drag Grip Indicator */}
              <div className="hidden sm:flex items-center gap-0.5 text-zinc-500 hover:text-zinc-300 transition-colors pointer-events-none">
                <GripHorizontal className="w-4 h-4 opacity-60" />
              </div>

              {/* Controls */}
              <div className="flex items-center gap-1.5 relative">
                <div className="relative">
                  <button
                    onClick={(e) => {
                      e.stopPropagation();
                      setIsMenuOpen(!isMenuOpen);
                    }}
                    title="More Options"
                    aria-expanded={isMenuOpen}
                    className="p-1.5 rounded-lg text-zinc-400 hover:text-white hover:bg-white/10 transition-colors cursor-pointer"
                  >
                    <MoreHorizontal className="w-4 h-4" />
                  </button>

                  {isMenuOpen && (
                    <div className="absolute right-0 top-full mt-1.5 w-44 bg-zinc-950/95 backdrop-blur-xl border border-white/15 rounded-xl shadow-2xl overflow-hidden py-1 z-50 text-xs">
                      <button
                        onClick={handleClear}
                        className="w-full text-left px-3.5 py-2 text-zinc-300 hover:bg-white/10 flex items-center gap-2 cursor-pointer transition-colors"
                      >
                        <RotateCcw className="w-3.5 h-3.5" />
                        <span>New Conversation</span>
                      </button>
                    </div>
                  )}
                </div>

                <button
                  onClick={(e) => {
                    e.stopPropagation();
                    setIsMinimized(!isMinimized);
                  }}
                  title={isMinimized ? "Maximize" : "Minimize"}
                  className="p-1.5 rounded-lg text-zinc-400 hover:text-white hover:bg-white/10 transition-colors cursor-pointer"
                >
                  {isMinimized ? <Maximize2 className="w-4 h-4" /> : <Minimize2 className="w-4 h-4" />}
                </button>
                <button
                  onClick={(e) => {
                    e.stopPropagation();
                    closeAssistant();
                  }}
                  title="Close Assistant"
                  className="p-1.5 rounded-lg text-zinc-400 hover:text-rose-400 hover:bg-rose-500/20 transition-colors cursor-pointer"
                >
                  <X className="w-4 h-4" />
                </button>
              </div>
            </div>

            {/* Body Content (Hidden when minimized) */}
            {!isMinimized && (
              <div className="flex-1 flex flex-col justify-between overflow-hidden relative">
                
                {/* Scrollable Container (Hero OR Messages) */}
                <div className="flex-1 p-5 overflow-y-auto space-y-4 scrollbar-thin bg-transparent">
                  
                  {/* Hero Initial Screen when no messages */}
                  {messages.length === 0 ? (
                    <div className="flex flex-col items-center text-center py-2 animate-in fade-in duration-300">
                      
                      {/* Big Glowing Cyclone Emblem */}
                      <div className="relative my-3 flex items-center justify-center">
                        <div className="absolute w-28 h-28 rounded-full bg-blue-500/25 blur-2xl pointer-events-none" />
                        <div className="w-20 h-20 rounded-2xl bg-blue-500/10 border border-blue-500/20 flex items-center justify-center relative shadow-lg shadow-blue-500/10">
                          <CycloneLogo size={54} />
                        </div>
                      </div>

                      {/* Main Greeting */}
                      <h2 className="text-2xl sm:text-3xl font-heading font-extrabold text-white mt-2 tracking-tight">
                        Hi, I&apos;m <span className="bg-gradient-to-r from-blue-400 via-sky-300 to-indigo-400 bg-clip-text text-transparent">CycloNet AI</span>
                      </h2>
                      <p className="text-xs sm:text-sm text-zinc-400 mt-1 max-w-sm">
                        Educational explanations and backend source summaries.
                      </p>

                      {/* Powered by divider */}
                      <div className="flex items-center gap-3 my-4 w-full max-w-xs">
                        <div className="h-px bg-white/10 flex-1" />
                        <span className="text-[10px] text-zinc-400 uppercase tracking-wider font-mono">
                          No generated operational advice
                        </span>
                        <div className="h-px bg-white/10 flex-1" />
                      </div>

                      {/* 4 Feature Cards (2x2 Grid) */}
                      <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 w-full max-w-md my-1 text-left">
                        {FEATURE_CARDS.map((card, idx) => {
                          const Icon = card.icon;
                          return (
                            <button
                              key={idx}
                              onClick={() => handleSend(card.query)}
                              className="p-3.5 rounded-2xl bg-card/60 hover:bg-card border border-border hover:border-primary/40 transition-all flex items-center justify-between gap-3 group cursor-pointer shadow-xs hover:scale-[1.01]"
                            >
                              <div className="flex items-center gap-3 min-w-0">
                                <div className={`w-10 h-10 rounded-xl flex items-center justify-center shrink-0 border ${card.iconBg} group-hover:scale-105 transition-transform`}>
                                  <Icon className="w-5 h-5" />
                                </div>
                                <div className="min-w-0">
                                  <h4 className="font-heading font-bold text-xs text-foreground group-hover:text-primary transition-colors truncate">
                                    {card.title}
                                  </h4>
                                  <p className="text-[10.5px] text-muted-foreground leading-tight truncate">
                                    {card.desc}
                                  </p>
                                </div>
                              </div>
                              <ChevronRight className="w-4 h-4 text-muted-foreground group-hover:text-foreground transition-colors shrink-0" />
                            </button>
                          );
                        })}
                      </div>

                    </div>
                  ) : (
                    /* Active Chat Stream */
                    <div role="log" aria-label="Conversation" aria-live="polite" aria-relevant="additions text" className="space-y-4">
                      {messages.map((msg) => (
                        <motion.div
                          key={msg.id}
                          initial={{ opacity: 0, y: 10 }}
                          animate={{ opacity: 1, y: 0 }}
                          transition={{ duration: 0.2 }}
                          className={`flex flex-col ${msg.role === "user" ? "items-end" : "items-start"}`}
                        >
                          <div
                            className={`group relative max-w-[88%] rounded-2xl p-3.5 text-sm leading-relaxed ${
                              msg.role === "user"
                                ? "bg-primary text-primary-foreground font-semibold rounded-tr-sm shadow-md"
                                : "bg-card/90 border border-border text-foreground rounded-tl-sm shadow-xs"
                            }`}
                          >
                            {formatContent(msg.content, msg.role === "user")}

                            {/* Copy button on assistant answers */}
                            {msg.role === "assistant" && (
                              <div className="mt-2 pt-2 border-t border-border flex items-center justify-between text-[10px] text-muted-foreground">
                                <span className="font-mono">{msg.timestamp}</span>
                                <button
                                  onClick={() => handleCopy(msg.content, msg.id)}
                                  className="flex items-center gap-1 hover:text-foreground transition-colors cursor-pointer"
                                >
                                  {copiedId === msg.id ? (
                                    <>
                                      <Check className="w-3 h-3 text-emerald-500" />
                                      <span className="text-emerald-500">Copied</span>
                                    </>
                                  ) : (
                                    <>
                                      <Copy className="w-3 h-3" />
                                      <span>Copy</span>
                                    </>
                                  )}
                                </button>
                              </div>
                            )}
                          </div>

                          {/* Source Citation Badges */}
                          {msg.sources && msg.sources.length > 0 && (
                            <div className="mt-1 flex flex-wrap gap-1 px-1">
                              {msg.sources.map((src, sIdx) => (
                                <span
                                  key={sIdx}
                                  className="text-[9px] px-2 py-0.5 rounded-full bg-secondary text-muted-foreground border border-border font-mono"
                                >
                                  📚 {src}
                                </span>
                              ))}
                            </div>
                          )}
                        </motion.div>
                      ))}

                      {/* Typing Indicator */}
                      {loading && (
                        <motion.div
                          initial={{ opacity: 0, y: 10 }}
                          animate={{ opacity: 1, y: 0 }}
                          className="flex items-start gap-2"
                        >
                          <div className="rounded-2xl rounded-tl-sm p-3 bg-card/90 border border-border flex items-center gap-1.5 shadow-xs">
                            <span className="w-2 h-2 rounded-full bg-primary animate-bounce [animation-delay:-0.3s]" />
                            <span className="w-2 h-2 rounded-full bg-primary animate-bounce [animation-delay:-0.15s]" />
                            <span className="w-2 h-2 rounded-full bg-primary animate-bounce" />
                            <span className="text-[11px] text-muted-foreground font-mono ml-2">
                              Preparing response…
                            </span>
                          </div>
                        </motion.div>
                      )}

                      <div ref={messagesEndRef} />
                    </div>
                  )}

                </div>

                {/* Bottom Input Section */}
                <div className="p-4 border-t border-white/10 bg-zinc-950/50 backdrop-blur-md">
                  
                  {/* Sleek Input Bar */}
                  <div className="flex items-center gap-2.5 rounded-full bg-zinc-900/80 border border-white/15 focus-within:border-blue-500/50 focus-within:ring-2 focus-within:ring-blue-500/20 px-4 py-2.5 shadow-inner transition-all">
                    <Sparkles className="w-4 h-4 text-blue-400 shrink-0" />
                    
                    <input
                      ref={inputRef}
                      aria-label="Message CycloNet AI"
                      type="text"
                      value={input}
                      maxLength={3000}
                      onChange={(e) => setInput(e.target.value)}
                      onKeyDown={(e) => {
                        if (e.key === "Enter") {
                          e.preventDefault();
                          handleSend();
                        }
                      }}
                      placeholder="Ask me anything about cyclones..."
                      className="min-w-0 flex-1 bg-transparent border-none outline-none text-xs text-white placeholder:text-zinc-400 leading-normal"
                    />

                    {/* Voice Input Mic Button */}
                    <button
                      type="button"
                      onClick={toggleVoiceInput}
                      title={isListening ? "Listening... Click to stop" : "Voice Input (Speak to CycloNet AI)"}
                      className={`p-1.5 rounded-full transition-all cursor-pointer ${
                        isListening
                          ? "bg-rose-500/20 text-rose-400 border border-rose-500/40 animate-pulse scale-110"
                          : "text-zinc-400 hover:text-white hover:bg-white/10"
                      }`}
                    >
                      {isListening ? (
                        <MicOff className="w-4 h-4 text-rose-400" />
                      ) : (
                        <Mic className="w-4 h-4" />
                      )}
                    </button>

                    <button
                      onClick={() => handleSend()}
                      disabled={!input.trim() || loading}
                      className="w-8 h-8 rounded-full bg-blue-500 hover:bg-blue-400 text-white disabled:opacity-30 disabled:pointer-events-none transition-all shadow-md shadow-blue-500/25 flex items-center justify-center shrink-0 cursor-pointer hover:scale-105"
                      title="Send Message"
                    >
                      <Send className="w-3.5 h-3.5 fill-current" />
                    </button>
                  </div>

                </div>

                {/* Corner Resize Handle */}
                <div
                  onMouseDown={handleResizeStart}
                  onTouchStart={handleResizeStart}
                  className="absolute bottom-0 right-0 w-6 h-6 cursor-nwse-resize flex items-end justify-end p-1 text-zinc-400 hover:text-white transition-colors z-30 select-none group"
                  title="Drag to resize chat window"
                >
                  <svg className="w-3.5 h-3.5 group-hover:scale-125 transition-transform" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round">
                    <line x1="21" y1="11" x2="11" y2="21" />
                    <line x1="21" y1="16" x2="16" y2="21" />
                  </svg>
                </div>

              </div>
            )}
          </motion.div>
        )}
      </AnimatePresence>
    </>
  );
}

"use client";
import type { TrackPoint } from "@/types/api";

import React, { useState } from 'react';
import { 
  MapContainer, 
  TileLayer, 
  CircleMarker, 
  Popup, 
  Polyline, 
  Tooltip, 
  useMap,
  ZoomControl 
} from 'react-leaflet';
import { Layers, Compass, Tag } from 'lucide-react';
import 'leaflet/dist/leaflet.css';
import L from 'leaflet';

// Fix default Leaflet icon paths
delete (L.Icon.Default.prototype as L.Icon.Default & { _getIconUrl?: unknown })._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl: 'https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon-2x.png',
  iconUrl: 'https://unpkg.com/leaflet@1.9.4/dist/images/marker-icon.png',
  shadowUrl: 'https://unpkg.com/leaflet@1.9.4/dist/images/marker-shadow.png',
});

function ChangeView({ center, zoom }: { center: [number, number]; zoom: number }) {
  const map = useMap();
  React.useEffect(() => {
    map.setView(center, zoom, { animate: true });
  }, [center, zoom, map]);
  return null;
}



interface CycloneComparisonSystem {
  id: string;
  name: string;
  basin: string;
  category: string;
  intensity_knots: number | null;
  track_forecast?: TrackPoint[];
  landfall_info?: import("@/types/api").LandfallInfo;
}

interface CompareMapProps {
  system1: CycloneComparisonSystem | null;
  system2: CycloneComparisonSystem | null;
}

// Helper to get yesterday's UTC date formatted for NASA GIBS daily WMTS tiles
const getGibsDate = () => {
  const d = new Date();
  d.setUTCDate(d.getUTCDate() - 1);
  return d.toISOString().split('T')[0];
};

const MAP_STYLES = {
  satellite: {
    name: '🗺️ Esri High-Res Multispectral Satellite',
    url: 'https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',
    attribution: 'Tiles &copy; Esri, USGS, NOAA'
  },
  nasa_viirs: {
    name: '🛰️ NASA VIIRS True-Color (EOSDIS)',
    url: `https://gibs.earthdata.nasa.gov/wmts/epsg3857/best/VIIRS_SNPP_CorrectedReflectance_TrueColor/default/${getGibsDate()}/GoogleMapsCompatible_Level9/{z}/{y}/{x}.jpg`,
    attribution: 'Imagery &copy; NASA EOSDIS GIBS / NOAA VIIRS'
  },
  dark: {
    name: '🌑 Tactical Disaster Command (Dark)',
    url: 'https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png',
    attribution: '&copy; CARTO &copy; OpenStreetMap contributors'
  },
  street: {
    name: '🧭 IMD Operational Geo Chart',
    url: 'https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',
    attribution: '&copy; OpenStreetMap contributors'
  }
};

type MapStyleKey = keyof typeof MAP_STYLES;

export default function CompareMapComponent({ system1, system2 }: CompareMapProps) {
  const [currentStyle, setCurrentStyle] = useState<MapStyleKey>('satellite');
  const [isLayerMenuOpen, setIsLayerMenuOpen] = useState(false);
  const [showLabels, setShowLabels] = useState(true);

  const pts1 = system1?.track_forecast || [];
  const pts2 = system2?.track_forecast || [];

  // Find max intensity indices for milestone labeling
  const maxIdx1 = React.useMemo(() => {
    if (pts1.length === 0) return -1;
    let maxK = -1;
    let idx = -1;
    pts1.forEach((p, i) => {
      if (p.intensity_knots != null && p.intensity_knots > maxK) {
        maxK = p.intensity_knots;
        idx = i;
      }
    });
    return idx;
  }, [pts1]);

  const maxIdx2 = React.useMemo(() => {
    if (pts2.length === 0) return -1;
    let maxK = -1;
    let idx = -1;
    pts2.forEach((p, i) => {
      if (p.intensity_knots != null && p.intensity_knots > maxK) {
        maxK = p.intensity_knots;
        idx = i;
      }
    });
    return idx;
  }, [pts2]);

  // Calculate center of all points
  const allPts = [...pts1, ...pts2];
  const center: [number, number] = allPts.length > 0 
    ? [
        allPts.reduce((acc, p) => acc + p.lat, 0) / allPts.length,
        allPts.reduce((acc, p) => acc + p.lon, 0) / allPts.length
      ]
    : [18.0, 84.0];

  return (
    <div className={`relative w-full h-full select-none ${!showLabels ? "hide-imd-labels" : ""}`}>
      {/* ── Top Left Header Badge ────────────────────────────────────────── */}
      <div className="absolute top-4 left-4 z-[1000] bg-card/95 backdrop-blur-md px-3.5 py-2 rounded-xl border border-border shadow-lg flex items-center gap-2.5 pointer-events-auto">
        <Compass className="w-4 h-4 text-cyan-400 shrink-0" />
        <div>
          <h4 className="font-heading font-semibold text-xs text-foreground">
            Dual-Track Comparative GIS Analysis
          </h4>
          <p className="text-[10.5px] text-muted-foreground">
            Overlaying historical best-tracks & landfall fixes
          </p>
        </div>
      </div>

      {/* ── Top Right Toolbar Controls ───────────────────────────────────── */}
      <div className="absolute top-4 right-4 z-[1000] flex items-center gap-2">
        <button
          onClick={() => setShowLabels(!showLabels)}
          className={`px-3 py-1.5 rounded-lg border text-xs font-semibold backdrop-blur-md shadow-md transition-all flex items-center gap-1.5 cursor-pointer ${
            showLabels 
              ? 'bg-blue-600 text-white border-blue-500 shadow-blue-500/20' 
              : 'bg-background/90 text-foreground/70 border-border hover:bg-secondary'
          }`}
          title="Toggle Track Milestone Labels"
        >
          <Tag className="w-3.5 h-3.5" />
          <span className="hidden sm:inline">Milestones</span>
        </button>

        {/* Map Style Selector */}
        <div className="relative">
          <button 
            onClick={() => setIsLayerMenuOpen(!isLayerMenuOpen)}
            className="bg-background/90 backdrop-blur-md p-2 rounded-lg border border-border shadow-md hover:bg-secondary transition-colors flex items-center justify-center cursor-pointer"
            title="Switch Map Layers (NASA VIIRS, MODIS, Satellite, Tactical Dark, IMD Geo)"
          >
            <Layers className="w-4 h-4 text-foreground" />
          </button>
          {isLayerMenuOpen && (
            <div className="absolute top-full right-0 mt-2 bg-background/95 backdrop-blur-xl border border-border rounded-xl shadow-xl overflow-hidden flex flex-col w-64 py-1 z-50">
              <div className="px-3 py-1.5 text-[10px] font-bold uppercase tracking-wider text-muted-foreground border-b border-border">
                Base Satellite & GIS Imagery Feed
              </div>
              {Object.entries(MAP_STYLES).map(([key, style]) => (
                <button
                  key={key}
                  onClick={() => {
                    setCurrentStyle(key as MapStyleKey);
                    setIsLayerMenuOpen(false);
                  }}
                  className={`text-left px-3.5 py-2 text-xs transition-colors flex items-center justify-between cursor-pointer ${
                    currentStyle === key 
                      ? 'bg-primary/15 text-primary font-bold' 
                      : 'text-foreground hover:bg-secondary'
                  }`}
                >
                  <span>{style.name}</span>
                  {currentStyle === key && <span className="w-1.5 h-1.5 rounded-full bg-primary" />}
                </button>
              ))}
            </div>
          )}
        </div>
      </div>

      {/* ── Bottom Left Dual Legend ──────────────────────────────────────── */}
      <div className="absolute bottom-6 left-6 z-[1000] bg-background/95 backdrop-blur-xl border border-border rounded-xl p-3 shadow-xl max-w-xs text-xs space-y-2 pointer-events-auto">
        <span className="font-heading font-bold text-foreground text-[11px] uppercase tracking-wide flex items-center gap-1.5 border-b border-border pb-1">
          <Compass className="w-3.5 h-3.5 text-blue-500" />
          Comparison Legend
        </span>
        <div className="space-y-1.5 text-[11px]">
          {system1 && (
            <div className="flex items-center gap-2">
              <span className="w-3 h-3 rounded-full bg-[#06b6d4] border border-white shadow-xs inline-block" />
              <span className="font-bold text-cyan-400">{system1.name} ({system1.category.split(" ")[0]})</span>
            </div>
          )}
          {system2 && (
            <div className="flex items-center gap-2">
              <span className="w-3 h-3 rounded-full bg-[#f59e0b] border border-white shadow-xs inline-block" />
              <span className="font-bold text-amber-400">{system2.name} ({system2.category.split(" ")[0]})</span>
            </div>
          )}
          <div className="flex items-center gap-2 pt-1 border-t border-border text-[10px] text-muted-foreground">
            <span>🎯 Red Ring Marker: Landfall Coastal Crossing</span>
          </div>
        </div>
      </div>

      {/* Global CSS overrides for Leaflet map styling */}
      <style jsx global>{`
        .hide-imd-labels .compare-milestone-label {
          display: none !important;
        }
        .compare-milestone-label {
          background: transparent !important;
          border: none !important;
          box-shadow: none !important;
          padding: 0 !important;
        }
      `}</style>

      <MapContainer 
        center={center} 
        zoom={5} 
        zoomControl={false}
        style={{ height: '100%', width: '100%' }}
        className="z-0"
      >
        <ZoomControl position="topright" />
        <ChangeView center={center} zoom={5} />
        <TileLayer
          key={currentStyle}
          attribution={MAP_STYLES[currentStyle].attribution}
          url={MAP_STYLES[currentStyle].url}
        />

        {/* ── System 1 Track (Cyan) ───────────────────────────────────────── */}
        {system1 && pts1.length > 0 && (
          <>
            {pts1.map((pt, idx) => {
              if (idx === 0) return null;
              const prev = pts1[idx - 1];
              return (
                <Polyline 
                  key={`sys1-seg-${idx}`} 
                  positions={[[prev.lat, prev.lon], [pt.lat, pt.lon]]} 
                  pathOptions={{
                    color: "#06b6d4",
                    weight: 3.5,
                    opacity: 0.95
                  }}
                />
              );
            })}

            {pts1.map((pt, idx) => {
              const isLandfall = pt.is_landfall || (pt.label && pt.label.toLowerCase().includes("landfall"));
              const isPeak = idx === maxIdx1;
              const isGenesis = idx === 0;
              const isMilestone = isLandfall || isPeak || isGenesis;

              return (
                <CircleMarker 
                  key={`sys1-pt-${idx}`}
                  center={[pt.lat, pt.lon]} 
                  radius={isLandfall ? 8 : (isPeak ? 7 : 5)} 
                  fillColor={isLandfall ? "#dc2626" : (isPeak ? "#06b6d4" : "#0891b2")} 
                  color="#ffffff" 
                  weight={isLandfall ? 3 : (isPeak ? 2.5 : 1.5)} 
                  fillOpacity={1}
                >
                  {showLabels && isMilestone ? (
                    <Tooltip permanent direction="right" offset={[10, 0]} className="compare-milestone-label">
                      <div className={`font-mono text-[10px] font-bold px-2 py-0.5 rounded shadow-lg backdrop-blur-md flex items-center gap-1 ${
                        isLandfall
                          ? "bg-red-950/95 text-red-200 border border-red-500/70"
                          : isPeak
                            ? "bg-cyan-950/95 text-cyan-200 border border-cyan-400 font-extrabold ring-1 ring-cyan-400/40"
                            : "bg-zinc-950/90 text-cyan-300 border border-cyan-500/40"
                      }`}>
                        {isLandfall && <span className="w-1.5 h-1.5 rounded-full bg-red-400 animate-pulse" />}
                        {isPeak && <span>⭐ PEAK:</span>}
                        <span>{system1.name}: {pt.intensity_knots ?? "Not available"}KT {isLandfall ? "(Landfall)" : ""}</span>
                      </div>
                    </Tooltip>
                  ) : (
                    <Tooltip direction="top" offset={[0, -6]}>
                      <span className="font-mono text-[10px] font-bold">
                        {system1.name}: {pt.intensity_knots ?? "Not available"} KT • {pt.category}
                      </span>
                    </Tooltip>
                  )}
                  <Popup>
                    <div className="p-1.5 space-y-1 text-xs">
                      <p className="font-bold text-cyan-400">{system1.name} — {pt.category}</p>
                      <p className="text-muted-foreground">Wind: <strong className="text-white">{pt.intensity_knots ?? "Not available"} KT ({(pt.intensity_knots == null ? null : Math.round(pt.intensity_knots * 1.852))} km/h)</strong></p>
                      <p className="text-muted-foreground">Fix: {pt.lat.toFixed(1)}°N, {pt.lon.toFixed(1)}°E</p>
                      {isLandfall && (
                        <p className="font-bold text-red-400 bg-red-950/50 p-1 rounded border border-red-500/30">
                          🎯 Landfall Coastal Crossing
                        </p>
                      )}
                    </div>
                  </Popup>
                </CircleMarker>
              );
            })}
          </>
        )}

        {/* ── System 2 Track (Amber) ──────────────────────────────────────── */}
        {system2 && pts2.length > 0 && (
          <>
            {pts2.map((pt, idx) => {
              if (idx === 0) return null;
              const prev = pts2[idx - 1];
              return (
                <Polyline 
                  key={`sys2-seg-${idx}`} 
                  positions={[[prev.lat, prev.lon], [pt.lat, pt.lon]]} 
                  pathOptions={{
                    color: "#f59e0b",
                    weight: 3.5,
                    dashArray: "6, 4",
                    opacity: 0.95
                  }}
                />
              );
            })}

            {pts2.map((pt, idx) => {
              const isLandfall = pt.is_landfall || (pt.label && pt.label.toLowerCase().includes("landfall"));
              const isPeak = idx === maxIdx2;
              const isGenesis = idx === 0;
              const isMilestone = isLandfall || isPeak || isGenesis;

              return (
                <CircleMarker 
                  key={`sys2-pt-${idx}`}
                  center={[pt.lat, pt.lon]} 
                  radius={isLandfall ? 8 : (isPeak ? 7 : 5)} 
                  fillColor={isLandfall ? "#dc2626" : (isPeak ? "#f59e0b" : "#d97706")} 
                  color="#ffffff" 
                  weight={isLandfall ? 3 : (isPeak ? 2.5 : 1.5)} 
                  fillOpacity={1}
                >
                  {showLabels && isMilestone ? (
                    <Tooltip permanent direction="left" offset={[-10, 0]} className="compare-milestone-label">
                      <div className={`font-mono text-[10px] font-bold px-2 py-0.5 rounded shadow-lg backdrop-blur-md flex items-center gap-1 ${
                        isLandfall
                          ? "bg-red-950/95 text-red-200 border border-red-500/70"
                          : isPeak
                            ? "bg-amber-950/95 text-amber-200 border border-amber-400 font-extrabold ring-1 ring-amber-400/40"
                            : "bg-zinc-950/90 text-amber-300 border border-amber-500/40"
                      }`}>
                        {isLandfall && <span className="w-1.5 h-1.5 rounded-full bg-red-400 animate-pulse" />}
                        {isPeak && <span>⭐ PEAK:</span>}
                        <span>{system2.name}: {pt.intensity_knots ?? "Not available"}KT {isLandfall ? "(Landfall)" : ""}</span>
                      </div>
                    </Tooltip>
                  ) : (
                    <Tooltip direction="top" offset={[0, -6]}>
                      <span className="font-mono text-[10px] font-bold">
                        {system2.name}: {pt.intensity_knots ?? "Not available"} KT • {pt.category}
                      </span>
                    </Tooltip>
                  )}
                  <Popup>
                    <div className="p-1.5 space-y-1 text-xs">
                      <p className="font-bold text-amber-400">{system2.name} — {pt.category}</p>
                      <p className="text-muted-foreground">Wind: <strong className="text-white">{pt.intensity_knots ?? "Not available"} KT ({(pt.intensity_knots == null ? null : Math.round(pt.intensity_knots * 1.852))} km/h)</strong></p>
                      <p className="text-muted-foreground">Fix: {pt.lat.toFixed(1)}°N, {pt.lon.toFixed(1)}°E</p>
                      {isLandfall && (
                        <p className="font-bold text-red-400 bg-red-950/50 p-1 rounded border border-red-500/30">
                          🎯 Landfall Coastal Crossing
                        </p>
                      )}
                    </div>
                  </Popup>
                </CircleMarker>
              );
            })}
          </>
        )}
      </MapContainer>
    </div>
  );
}

"use client";
import { useMounted } from "@/hooks/useBrowserState";

import React from "react";
import { Menu, Wind } from "lucide-react";
import { usePathname } from "next/navigation";
import { useActiveCyclone } from "@/hooks/useActiveCyclone";
import { CycloneLogo } from "@/components/CycloneLogo";
import { NeonThemeToggle } from "@/components/NeonThemeToggle";
import { navItems } from "@/components/Sidebar";

export function Header() {
  const mounted = useMounted();
  const pathname = usePathname();
  const { selectedCycloneId, selectedCycloneName } = useActiveCyclone();



  const getPageTitle = () => {
    switch (pathname) {
      case "/":
      case "/dashboard": return "Live Monitoring";
      case "/classification": return "Classification";
      case "/archive": return "Historical Archive";
      case "/compare": return "Storm Comparison";
      case "/forecast": return "Track Forecast";
      case "/reports": return "Alerts & Reports";
      case "/infrastructure": return "Infrastructure & Relief";
      case "/settings": return "Settings";
      default: return "Dashboard";
    }
  };

  const formatDisplayCycloneName = (name?: string | null) => {
    if (!name) return "";
    const n = name.trim();
    const lower = n.toLowerCase();
    if (
      lower.startsWith("cyclone") ||
      lower.startsWith("super cyclone") ||
      lower.includes("depression") ||
      lower.includes("low")
    ) {
      return n;
    }
    return `Cyclone ${n}`;
  };

  return (
    <header className="min-h-16 shrink-0 border-b border-border bg-background/50 backdrop-blur-xl sticky top-0 z-30 flex items-center justify-between gap-3 px-4 sm:px-6">
      <div className="flex min-w-0 items-center gap-2 sm:gap-4">
        <button aria-label="Open navigation" popoverTarget="mobile-navigation" className="lg:hidden p-2 -ml-2 text-muted-foreground hover:text-foreground rounded-lg hover:bg-secondary">
          <Menu className="w-5 h-5" />
        </button>
        <nav id="mobile-navigation" popover="auto" aria-label="Mobile navigation" className="fixed inset-auto top-16 left-4 m-0 w-[calc(100vw-2rem)] max-w-sm rounded-xl border border-border bg-card p-2 text-foreground shadow-xl">
          {navItems.map(({name,href,icon:Icon})=><a key={href} href={href} aria-current={pathname===href ? 'page' : undefined} className="flex items-center gap-3 rounded-lg px-3 py-3 text-sm hover:bg-secondary focus-visible:outline-2 focus-visible:outline-primary"><Icon className="h-4 w-4" />{name}</a>)}
        </nav>
        <h1 className="font-heading font-semibold text-base sm:text-lg truncate">{getPageTitle()}</h1>
        {selectedCycloneId && mounted && (
          <a
            href={`/forecast?cyclone_id=${encodeURIComponent(selectedCycloneId)}`}
            className="hidden sm:flex items-center gap-1.5 px-2.5 py-1 rounded-full bg-emerald-500/10 hover:bg-emerald-500/20 text-emerald-400 border border-emerald-500/30 text-xs font-medium transition-all shadow-xs"
            title="Selected record; selection does not establish current storm activity"
          >
            <span className="w-1.5 h-1.5 rounded-full bg-current" />
            <span>Selected: {selectedCycloneName ? formatDisplayCycloneName(selectedCycloneName) : selectedCycloneId}</span>
          </a>
        )}
      </div>

      <div className="flex shrink-0 items-center gap-2 sm:gap-3">
        {/* Ask CycloNet AI Button with Animated Green Gradient Effect */}
        <button
          onClick={() => {
            if (typeof window !== "undefined") {
              window.dispatchEvent(new CustomEvent("cyclonet:open-chat"));
            }
          }}
          className="buttonupgrade group"
          title="Open CycloNet AI Meteorological Intelligence"
          aria-label="Ask CycloNet AI"
        >
          <div className="relative flex items-center justify-center shrink-0">
            <CycloneLogo size={20} />
          </div>
          <span className="hidden sm:inline">Ask CycloNet AI</span>
        </button>

        <NeonThemeToggle size="sm" />
        
        <a
          href="/settings"
          className="h-8 w-8 rounded-full bg-gradient-to-tr from-indigo-600 to-violet-500 text-white flex items-center justify-center font-bold text-xs shadow-xs ring-1 ring-indigo-500/20 hover:scale-105 transition-transform"
          title="Account settings"
          aria-label="Account settings"
        >
          <span>Me</span>
        </a>
      </div>
    </header>
  );
}

