});





interface MapProps {
  activeSystem: ActiveSystem | null;
}

// Helper to get yesterday's UTC date formatted for NASA GIBS daily WMTS tiles
const getGibsDate = () => {
  const d = new Date();
  d.setUTCDate(d.getUTCDate() - 1);
  return d.toISOString().split('T')[0];
};

const MAP_STYLES = {
  satellite: {
    name: '🗺️ Esri High-Res Multispectral Satellite',
    url: 'https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',
    attribution: 'Tiles &copy; Esri, USGS, NOAA &mdash; Multispectral Feed'
  },
  nasa_viirs: {
    name: '🛰️ NASA VIIRS daily imagery (prior date)',
    url: `https://gibs.earthdata.nasa.gov/wmts/epsg3857/best/VIIRS_SNPP_CorrectedReflectance_TrueColor/default/${getGibsDate()}/GoogleMapsCompatible_Level9/{z}/{y}/{x}.jpg`,
    attribution: 'Imagery &copy; NASA EOSDIS GIBS / NOAA VIIRS'
  },
  dark: {
    name: '🌑 Tactical Disaster Command (Dark)',
    url: 'https://{s}.basemaps.cartocdn.com/dark_all/{z}/{x}/{y}{r}.png',
    attribution: '&copy; CARTO &copy; OpenStreetMap contributors'
  },
  street: {
    name: '🧭 IMD Operational Nautical Chart',
    url: 'https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',
    attribution: '&copy; OpenStreetMap contributors &copy; IMD RSMC Best-Track'
  }
};

type MapStyleKey = keyof typeof MAP_STYLES;
type InfraFilter = 'all' | 'power' | 'roads' | 'shelters' | 'parametric';

const getIntensityColor = (knots: number | null) => {
  if (knots == null) return "#94a3b8";
  if (knots < 34) return "#a855f7"; // Purple (Depression)
  if (knots < 48) return "#3b82f6"; // Blue (Cyclonic Storm)
  if (knots < 64) return "#10b981"; // Green (Severe)
  if (knots < 90) return "#f59e0b"; // Orange (Very Severe)
  if (knots < 120) return "#ef4444"; // Red (Extremely Severe)
  return "#7f1d1d"; // Dark Red (Super Cyclone)
};

const getCategoryAbbr = (cat: string, knots: number | null): string => {
  if (knots == null) return "Not available";
  const c = (cat || "").toLowerCase();
  if (c.includes("super")) return "SuCS";
  if (c.includes("extremely")) return "ESCS";
  if (c.includes("very severe")) return "VSCS";
  if (c.includes("severe")) return "SCS";
  if (c.includes("cyclonic")) return "CS";
  if (c.includes("deep depression")) return "DD";
  if (c.includes("depression")) return "D";
  if (knots >= 120) return "SuCS";
  if (knots >= 90) return "ESCS";
  if (knots >= 65) return "VSCS";
  if (knots >= 48) return "SCS";
  if (knots >= 34) return "CS";
  if (knots >= 28) return "DD";
  return "D";
};

export default function MapComponent({ activeSystem }: MapProps) {
  // Default to Satellite View on application startup
  const [currentStyle, setCurrentStyle] = useState<MapStyleKey>('satellite');
  const [isLayerMenuOpen, setIsLayerMenuOpen] = useState(false);
  const [showLabels, setShowLabels] = useState(true);

  const [showLegend, setShowLegend] = useState(true);
  const [infraFilter, setInfraFilter] = useState<InfraFilter>('all');
  const [showInfra, setShowInfra] = useState(false);
  
  const center: [number, number] = activeSystem ? [activeSystem.lat, activeSystem.lon] : [17.5, 83.5];
  const zoomLevel = activeSystem ? 6 : 5;

  const points = activeSystem?.track_forecast || [];

  // Split points into observed past points and future forecast points
  const { observedPoints, forecastPoints, currentPoint } = useMemo(() => {
    if (!points || points.length === 0) {
      return { observedPoints: [], forecastPoints: [], currentPoint: null };
    }

    const past = points.filter(p => !p.is_forecast);
    const future = points.filter(p => p.is_forecast);
    
    const curr = past.length > 0 
      ? past[past.length - 1] 
      : { 
          lat: activeSystem!.lat, 
          lon: activeSystem!.lon, 
          intensity_knots: activeSystem!.intensity_knots, 
          category: activeSystem!.category, 
          time_offset_hours: 0, 
          is_forecast: false,
          is_landfall: false,
          label: `${activeSystem!.intensity_knots ?? "Not available"}KT,${getCategoryAbbr(activeSystem!.category, activeSystem!.intensity_knots)}`
        };

    return {
      observedPoints: past,
      forecastPoints: future,
      currentPoint: curr
    };
  }, [points, activeSystem]);

  const getPointLabel = (pt: TrackPoint) => {
    const raw = pt.label || "";
    const isLandfallPt = pt.is_landfall || (raw && raw.toLowerCase().includes("landfall"));
    if (raw) {
      // Compact badge string e.g. "25/06,35KT,DD (Landfall: Near Kalingapatnam)" -> "25/06 • 35KT • DD (Landfall)"
      const parts = raw.split("(");
      const codePart = parts[0].trim().replace(/,/g, " • ");
      if (isLandfallPt) {
        return `${codePart} • Landfall`;
      }
      return codePart;
    }
    const offsetH = pt.time_offset_hours || 0;
    const now = new Date();
    const synopticH = Math.floor(now.getUTCHours() / 6) * 6;
    const baseDate = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate(), synopticH, 0, 0));
    const ptDate = new Date(baseDate.getTime() + offsetH * 3600 * 1000);
    const day = ptDate.getUTCDate();
    const hr = ptDate.getUTCHours();
    const abbr = getCategoryAbbr(pt.category, pt.intensity_knots);
    const suffix = isLandfallPt ? " • Landfall" : "";
    return `${String(day).padStart(2, '0')}/${String(hr).padStart(2, '0')} • ${pt.intensity_knots ?? "Not available"}KT • ${abbr}${suffix}`;
  };

  return (
    <div className={`relative w-full h-full select-none ${!showLabels ? "hide-imd-labels" : ""}`}>
      
      {/* ── Top Left Live Surveillance Badge & Infrastructure Layer Filter ─────── */}
      <div className="absolute top-4 left-4 z-[1000] flex flex-col gap-2 pointer-events-auto">
        <div className="bg-card/95 backdrop-blur-md px-3.5 py-2 rounded-xl border border-border shadow-lg flex items-center gap-2.5">
          <div className="w-2.5 h-2.5 rounded-full bg-emerald-500 animate-pulse shrink-0" />
          <div>
            <h4 className="font-heading font-semibold text-xs text-foreground">
              INSAT-3DR Satellite Live Surveillance
            </h4>
            <p className="text-[10.5px] text-muted-foreground">
              {activeSystem ? `Tracking: ${activeSystem.name}` : "North Indian Ocean Basin • Current status unverified"}
            </p>
          </div>
        </div>

        {/* Infrastructure Layer Filter Pills */}
        <div className="flex flex-wrap items-center gap-1.5 bg-background/95 backdrop-blur-xl p-1.5 rounded-xl border border-border shadow-xl">
          <button
            onClick={() => setShowInfra(!showInfra)}
            className={`px-2.5 py-1 rounded-lg text-xs font-bold transition-all flex items-center gap-1.5 cursor-pointer ${
              showInfra 
                ? 'bg-primary text-primary-foreground shadow-sm' 
                : 'bg-secondary text-muted-foreground hover:text-foreground'
            }`}
            title="Toggle illustrative scenario assets — unverified"
          >
            <ShieldCheck className="w-3.5 h-3.5" />
            <span>Scenario assets (unverified)</span>
          </button>

          {showInfra && (
            <div className="flex items-center gap-1 border-l border-border pl-1.5 flex-wrap">
              <button
                onClick={() => setInfraFilter('all')}
                className={`px-2 py-0.5 rounded text-[11px] font-semibold transition-all cursor-pointer ${
                  infraFilter === 'all' ? 'bg-secondary text-foreground font-bold border border-border' : 'text-muted-foreground hover:text-foreground'
                }`}
              >
                All
              </button>
              <button
                onClick={() => setInfraFilter('power')}
                className={`px-2 py-0.5 rounded text-[11px] font-semibold transition-all flex items-center gap-1 cursor-pointer ${
                  infraFilter === 'power' ? 'bg-amber-500/20 text-amber-300 font-bold border border-amber-500/30' : 'text-muted-foreground hover:text-foreground'
                }`}
              >
                <Zap className="w-3 h-3 text-amber-400" /> Grids
              </button>
              <button
                onClick={() => setInfraFilter('roads')}
                className={`px-2 py-0.5 rounded text-[11px] font-semibold transition-all flex items-center gap-1 cursor-pointer ${
                  infraFilter === 'roads' ? 'bg-blue-500/20 text-blue-300 font-bold border border-blue-500/30' : 'text-muted-foreground hover:text-foreground'
                }`}
              >
                <Navigation className="w-3 h-3 text-blue-400" /> Roads
              </button>
              <button
                onClick={() => setInfraFilter('shelters')}
                className={`px-2 py-0.5 rounded text-[11px] font-semibold transition-all flex items-center gap-1 cursor-pointer ${
                  infraFilter === 'shelters' ? 'bg-emerald-500/20 text-emerald-300 font-bold border border-emerald-500/30' : 'text-muted-foreground hover:text-foreground'
                }`}
              >
                <Building2 className="w-3 h-3 text-emerald-400" /> Shelters
              </button>
              <button
                onClick={() => setInfraFilter('parametric')}
                className={`px-2 py-0.5 rounded text-[11px] font-semibold transition-all flex items-center gap-1 cursor-pointer ${
                  infraFilter === 'parametric' ? 'bg-cyan-500/20 text-cyan-300 font-bold border border-cyan-500/30' : 'text-muted-foreground hover:text-foreground'
                }`}
              >
                <ShieldAlert className="w-3 h-3 text-cyan-400" /> Surge
              </button>
            </div>
          )}
        </div>
      </div>

      {/* ── IMD Top Right Toolbar Controls ─────────────────────────────────── */}
      <div className="absolute top-4 right-4 z-[1000] flex items-center gap-1.5 flex-wrap justify-end">
        {/* Toggle IMD Labels Button */}
        <button
          onClick={() => setShowLabels(!showLabels)}
          className={`px-2.5 py-1.5 rounded-lg border text-xs font-semibold backdrop-blur-md shadow-md transition-all flex items-center gap-1.5 cursor-pointer ${
            showLabels 
              ? 'bg-blue-600 text-white border-blue-500 shadow-blue-500/20' 
              : 'bg-background/90 text-foreground/70 border-border hover:bg-secondary'
          }`}
          title="Toggle IMD Bullet Labels (DD/HH, Wind, Category)"
        >
          <Tag className="w-3.5 h-3.5" />
          <span className="hidden sm:inline">Labels</span>
        </button>

        <span className="text-xs bg-background/90 p-2 rounded">Uncertainty: Not validated</span>

        {/* Map Style Selector */}
        <div className="relative">
          <button 
            onClick={() => setIsLayerMenuOpen(!isLayerMenuOpen)}
            className="bg-background/90 backdrop-blur-md p-2 rounded-lg border border-border shadow-md hover:bg-secondary transition-colors flex items-center justify-center cursor-pointer"
            title="Switch Map Layers (NASA VIIRS, MODIS, base imagery, Dark Tactical, IMD Chart)"
          >
            <Layers className="w-4 h-4 text-foreground" />
          </button>
          {isLayerMenuOpen && (
            <div className="absolute top-full right-0 mt-2 bg-background/95 backdrop-blur-xl border border-border rounded-xl shadow-xl overflow-hidden flex flex-col w-64 py-1 z-50">
              <div className="px-3 py-1.5 text-[10px] font-bold uppercase tracking-wider text-muted-foreground border-b border-border">
                Base Satellite & GIS Imagery Feed
              </div>
              {Object.entries(MAP_STYLES).map(([key, style]) => (
                <button
                  key={key}
                  onClick={() => {
                    setCurrentStyle(key as MapStyleKey);
                    setIsLayerMenuOpen(false);
                  }}
                  className={`text-left px-3.5 py-2 text-xs transition-colors flex items-center justify-between cursor-pointer ${
                    currentStyle === key 
                      ? 'bg-primary/15 text-primary font-bold' 
                      : 'text-foreground hover:bg-secondary'
                  }`}
                >
                  <span>{style.name}</span>
                  {currentStyle === key && <span className="w-1.5 h-1.5 rounded-full bg-primary" />}
                </button>
              ))}
            </div>
          )}
        </div>
      </div>

      {/* Official IMD Track & Layer Legend (Bottom-Left) */}
      {showLegend && activeSystem && (
        <div className="absolute bottom-6 left-6 z-[1000] bg-background/95 backdrop-blur-xl border border-border rounded-xl p-3 shadow-xl max-w-xs text-xs space-y-2">
          <div className="flex items-center justify-between gap-3 border-b border-border pb-1.5">
            <span className="font-heading font-bold text-foreground text-[11px] uppercase tracking-wide flex items-center gap-1.5">
              <Compass className="w-3.5 h-3.5 text-blue-500" />
              IMD & Geospatial Legend
            </span>
            <button 
              onClick={() => setShowLegend(false)}
              className="text-muted-foreground hover:text-foreground text-[10px] cursor-pointer"
            >
              Hide
            </button>
          </div>
          <div className="space-y-1.5 text-[11px]">
            {/* Intensity Scale Badges */}
            <div className="grid grid-cols-3 gap-1 pb-1.5 border-b border-border text-[10px]">
              <span className="flex items-center gap-1.5 text-muted-foreground">
                <span className="w-2 h-2 rounded-full bg-[#a855f7] inline-block" /> D/DD
              </span>
              <span className="flex items-center gap-1.5 text-muted-foreground">
                <span className="w-2 h-2 rounded-full bg-[#3b82f6] inline-block" /> CS
              </span>
              <span className="flex items-center gap-1.5 text-muted-foreground">
                <span className="w-2 h-2 rounded-full bg-[#10b981] inline-block" /> SCS
              </span>
              <span className="flex items-center gap-1.5 text-muted-foreground">
                <span className="w-2 h-2 rounded-full bg-[#f59e0b] inline-block" /> VSCS
              </span>
              <span className="flex items-center gap-1.5 text-muted-foreground">
                <span className="w-2 h-2 rounded-full bg-[#ef4444] inline-block" /> ESCS
              </span>
              <span className="flex items-center gap-1.5 text-muted-foreground">
                <span className="w-2 h-2 rounded-full bg-[#7f1d1d] inline-block" /> SuCS
              </span>
            </div>
            
            {/* Infrastructure Symbols */}
            <div className="space-y-1 text-[10.5px] border-b border-border pb-1.5">
              <div className="flex items-center gap-2">
                <span className="w-2.5 h-2.5 rounded-full bg-amber-400 border border-amber-500 inline-block" />
                <span className="text-muted-foreground">⚡ 400kV/220kV Power Grid Substation</span>
              </div>
              <div className="flex items-center gap-2">
                <span className="w-2.5 h-2.5 rounded-full bg-emerald-400 border border-emerald-500 inline-block" />
                <span className="text-muted-foreground">🏥 Cyclone Shelter & Trauma Hospital</span>
              </div>
              <div className="flex items-center gap-2">
                <span className="w-4 h-1 rounded bg-blue-500 inline-block" />
                <span className="text-muted-foreground">🛣️ NH Arterial Evacuation Route</span>
              </div>
              <div className="flex items-center gap-2">
                <span className="w-4 h-2 rounded-xs bg-cyan-500/40 border border-cyan-400 inline-block" />
                <span className="text-muted-foreground">🌊 Parametric Surge Inundation Zone</span>
              </div>
            </div>

            <div className="flex items-center gap-2">
              <span className="w-4 h-0.5 bg-foreground/80 inline-block" />
              <span className="text-muted-foreground">
                {activeSystem?.telemetry_type === "HISTORICAL_BEST_TRACK" || activeSystem?.is_simulation
                  ? "Solid Line: Historical Best-Track"
                  : "Solid Line: Observed Track / 0h Fix"}
              </span>
            </div>
            <div className="flex items-center gap-2">
              <span className="w-4 h-0 border-t-2 border-dashed border-foreground/80 inline-block" />
              <span className="text-muted-foreground">
                {activeSystem?.telemetry_type === "HISTORICAL_BEST_TRACK" || activeSystem?.is_simulation
                  ? "Dashed Line: Post-Peak Best-Track Decay"
                  : "Dashed Line: BAM Dynamic Numerical Track"}
              </span>
            </div>
            <div className="flex items-center gap-2">
              <span className="w-4 h-2 rounded-xs bg-[#22c55e]/35 border border-[#15803d] inline-block" />
              <span className="text-muted-foreground text-[10px]">Green Cone: IMD 5-Yr Verification Error Envelope</span>
            </div>
          </div>
        </div>
      )}

      {/* Global CSS overrides for Leaflet map styling */}
      <style jsx global>{`
        .hide-imd-labels .imd-bullet-label {
          display: none !important;
        }
        .imd-bullet-label {
          background: transparent !important;
          border: none !important;
          box-shadow: none !important;
          padding: 0 !important;
        }
        .leaflet-tooltip-left:before, 
        .leaflet-tooltip-right:before,
        .leaflet-tooltip-top:before,
        .leaflet-tooltip-bottom:before {
          display: none !important;
        }
        .leaflet-popup-content-wrapper {
          background: rgba(15, 23, 42, 0.95) !important;
          backdrop-filter: blur(12px) !important;
          color: #f8fafc !important;
          border: 1px solid rgba(255, 255, 255, 0.1) !important;
          border-radius: 0.75rem !important;
          box-shadow: 0 20px 25px -5px rgba(0, 0, 0, 0.5), 0 8px 10px -6px rgba(0, 0, 0, 0.5) !important;
        }
        .leaflet-popup-tip {
          background: rgba(15, 23, 42, 0.95) !important;
        }
        .leaflet-control-zoom {
          border: 1px solid rgba(255, 255, 255, 0.1) !important;
          border-radius: 0.5rem !important;
          overflow: hidden !important;
          box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.3) !important;
          margin-top: 5rem !important;
          margin-right: 1rem !important;
        }
        .leaflet-control-zoom a {
          background: rgba(15, 23, 42, 0.85) !important;
          backdrop-filter: blur(8px) !important;
          color: #94a3b8 !important;
          border-bottom: 1px solid rgba(255, 255, 255, 0.1) !important;
          transition: all 0.2s ease !important;
        }
        .leaflet-control-zoom a:last-child {
          border-bottom: none !important;
        }
        .leaflet-control-zoom a:hover {
          background: rgba(255, 255, 255, 0.18) !important;
          color: #ffffff !important;
        }
      `}</style>

      <MapContainer 
        center={center} 
        zoom={zoomLevel} 
        zoomControl={false}
        style={{ height: '100%', width: '100%' }}
        className={`z-0 ${!showLabels ? "hide-imd-labels" : ""}`}
      >
        <ZoomControl position="topright" />
        <ChangeView center={center} zoom={zoomLevel} />
        
        {/* Base Satellite / Map Tile Feed */}
        <TileLayer
          key={currentStyle}
          attribution={MAP_STYLES[currentStyle].attribution}
          url={MAP_STYLES[currentStyle].url}
        />

        {/* ── Critical Infrastructure Layers ─────────────────────────────────── */}
        {showInfra && (
          <>
            <div className="absolute bottom-2 left-2 z-[1000] bg-background p-2 text-xs">ILLUSTRATIVE ASSETS — all coordinates and capacities unverified; road status unknown.</div>
            {/* 1. Parametric Inundation Zones (Surge Buffer Polygons) */}
            {(infraFilter === 'all' || infraFilter === 'parametric') && (
              COASTAL_INUNDATION_ZONES.map((zone, i) => (
                <Polygon
                  key={`inundation-${i}`}
                  positions={zone.polygon}
                  pathOptions={{
                    fillColor: "#06b6d4",
                    fillOpacity: 0.28,
                    color: "#0891b2",
                    weight: 2,
                    dashArray: "4, 4"
                  }}
                >
                  <Popup>
                    <div className="p-1 space-y-1 text-xs text-white">
                      <p className="font-bold text-cyan-400 flex items-center gap-1.5 text-sm">
                        <ShieldAlert className="w-4 h-4 text-cyan-400 shrink-0" />
                        <span>{zone.name}</span>
                      </p>
                      <p className="text-zinc-300 text-[11px]">Scenario depth: <strong className="text-white">{zone.depthM}</strong></p>
                      <p className="text-zinc-400 text-[10.5px]">Parametric Trigger: <span className="text-cyan-300 font-medium">No verified funding or insurance contract</span></p>
                    </div>
                  </Popup>
                  <Tooltip direction="center">
                    <span className="text-[10px] font-bold font-mono text-cyan-300 bg-zinc-950/80 px-1.5 py-0.5 rounded border border-cyan-500/40">
                      🌊 {zone.riskLevel}
                    </span>
                  </Tooltip>
                </Polygon>
              ))
            )}

            {/* 2. Arterial Evacuation Routes & Cutoffs */}
            {(infraFilter === 'all' || infraFilter === 'roads') && (
              EVACUATION_ROUTES.map((route, i) => (
                <Polyline
                  key={`route-${i}`}
                  positions={route.path}
                  pathOptions={{
                    color: route.floodRiskLevel.includes("Severe") ? "#ef4444" : "#3b82f6",
                    weight: 4,
                    opacity: 0.85,
                    dashArray: route.floodRiskLevel.includes("Severe") ? "8, 4" : undefined
                  }}
                >
                  <Popup>
                    <div className="p-1.5 space-y-1.5 text-xs text-white">
                      <p className="font-bold text-white text-sm">{route.name}</p>
                      <p className="text-[11px] text-zinc-300">Scenario category: <strong className="text-white">{route.evacuationPriority}</strong></p>
                      <p className={`text-[11px] font-semibold ${route.floodRiskLevel.includes("Severe") ? "text-red-400" : "text-blue-400"}`}>
                        Scenario risk: {route.floodRiskLevel}
                      </p>
                    </div>
                  </Popup>
                  <Tooltip direction="top">
                    <span className="text-[10px] font-bold font-mono text-white bg-blue-900/90 px-1.5 py-0.5 rounded border border-blue-400/40">
                      🛣️ {route.highwayCode} ({route.evacuationPriority.split(" ")[0]})
                    </span>
                  </Tooltip>
                </Polyline>
              ))
            )}

            {/* 3. Power Grid Substations */}
            {(infraFilter === 'all' || infraFilter === 'power') && (
              POWER_SUBSTATIONS.map((sub, i) => (
                <CircleMarker
                  key={`sub-${i}`}
                  center={[sub.lat, sub.lon]}
                  radius={7}
                  fillColor="#f59e0b"
                  color="#ffffff"
                  weight={2}
                  fillOpacity={0.95}
                >
                  <Popup>
                    <div className="p-1.5 space-y-1.5 text-xs text-white">
                      <div className="flex items-center gap-1.5 text-amber-400 font-bold text-sm">
                        <Zap className="w-4 h-4 shrink-0" />
                        <span>{sub.name}</span>
                      </div>
                      <p className="text-zinc-300 text-[11px]">Type: <strong className="text-white">{sub.type}</strong></p>
                      <p className="text-zinc-300 text-[11px]">Assumed capacity: <strong className="text-white">{sub.capacityMVA} MVA</strong></p>
                      <p className="text-zinc-300 text-[11px]">Coastal Distance: <strong className="text-white">{sub.coastalDistanceKm} km</strong> (Elev: {sub.elevationMeters}m)</p>
                      <span className="inline-block px-2.5 py-1 mt-1 rounded-md text-[10.5px] font-bold bg-amber-500/20 text-amber-300 border border-amber-500/40">
                        Criticality: {sub.criticality}
                      </span>
                    </div>
                  </Popup>
                  <Tooltip direction="top" offset={[0, -6]}>
                    <span className="text-[9.5px] font-bold font-mono text-amber-200 bg-zinc-950/90 px-1 py-0.5 rounded border border-amber-500/30">
                      ⚡ {sub.name.split(" ")[0]} ({sub.capacityMVA}MVA)
                    </span>
                  </Tooltip>
                </CircleMarker>
              ))
            )}

            {/* 4. Cyclone Shelters & Trauma Hospitals */}
            {(infraFilter === 'all' || infraFilter === 'shelters') && (
              MEDICAL_SHELTERS.map((shl, i) => (
                <CircleMarker
                  key={`shl-${i}`}
                  center={[shl.lat, shl.lon]}
                  radius={7}
                  fillColor="#10b981"
                  color="#ffffff"
                  weight={2}
                  fillOpacity={0.95}
                >
                  <Popup>
                    <div className="p-1.5 space-y-1.5 text-xs text-white">
                      <div className="flex items-center gap-1.5 text-emerald-400 font-bold text-sm">
                        <Building2 className="w-4 h-4 shrink-0" />
                        <span>{shl.name}</span>
                      </div>
                      <p className="text-zinc-300 text-[11px]">Type: <strong className="text-white">{shl.type}</strong></p>
                      <p className="text-zinc-300 text-[11px]">Assumed capacity: <strong className="text-white">{shl.capacityPersons.toLocaleString()} persons</strong></p>
                      <p className="text-zinc-300 text-[11px]">Assumed beds: <strong className="text-white">{shl.medicalBeds} Beds</strong></p>
                      <p className="text-zinc-300 text-[10.5px]">Backup Power: <strong className="text-white">{"Unavailable"}</strong></p>
                      <span className="inline-block px-2.5 py-1 mt-1 rounded-md text-[10.5px] font-bold bg-emerald-500/20 text-emerald-300 border border-emerald-500/40">
                        Status: {"Operational status not verified"}
                      </span>
                    </div>
                  </Popup>
                  <Tooltip direction="top" offset={[0, -6]}>
                    <span className="text-[9.5px] font-bold font-mono text-emerald-200 bg-zinc-950/90 px-1 py-0.5 rounded border border-emerald-500/30">
                      🏥 {shl.name.split(" ")[0]} ({shl.capacityPersons}p)
                    </span>
                  </Tooltip>
                </CircleMarker>
              ))
            )}
          </>
        )}

        {/* ── Tropical Cyclone Best-Track Geometry ─────────────────────────── */}
        {activeSystem && (
          <>
            {/* 2. Track Segments Colored by Severity */}
            {points.map((pt, idx) => {
              if (idx === 0) return null;
              const prevPt = points[idx - 1];
              const color = getIntensityColor(pt.intensity_knots);
              
              return (
                <Polyline 
                  key={`seg-${idx}`} 
                  positions={[[prevPt.lat, prevPt.lon], [pt.lat, pt.lon]]} 
                  pathOptions={{
                    color: color,
                    weight: 3.5,
                    dashArray: pt.is_forecast ? "6, 6" : undefined,
                    opacity: 0.95
                  }}
                />
              );
            })}

            {/* 3. Track Point Markers Colored by Actual Severity */}
            {points.map((pt, idx) => {
              const label = getPointLabel(pt);
              const color = getIntensityColor(pt.intensity_knots);
              const isLandfallPt = pt.is_landfall || (pt.label && pt.label.toLowerCase().includes("landfall"));

              return (
                <React.Fragment key={`pt-group-${idx}`}>
                  <CircleMarker 
                    center={[pt.lat, pt.lon]} 
                    radius={isLandfallPt ? 8 : (pt.is_forecast ? 5.5 : 5)} 
                    fillColor={isLandfallPt ? "#dc2626" : color} 
                    color="#ffffff" 
                    weight={isLandfallPt ? 3 : 1.5} 
                    fillOpacity={1}
                  >
                    {showLabels && (
                      <Tooltip 
                        permanent
                        direction="right" 
                        offset={[10, 0]} 
                        className="imd-bullet-label"
                      >
                        <div className={`font-mono text-[10px] font-bold whitespace-nowrap px-2 py-0.5 rounded-md backdrop-blur-md transition-all shadow-md ${
                          isLandfallPt 
                            ? "bg-red-950/95 text-red-100 border border-red-500/80 shadow-red-950/40 flex items-center gap-1"
                            : pt.is_forecast 
                              ? "bg-zinc-950/90 text-red-300 border border-red-500/35" 
                              : "bg-zinc-950/90 text-zinc-200 border border-zinc-700/60"
                        }`}>
                          {isLandfallPt && <span className="w-1.5 h-1.5 rounded-full bg-red-400 animate-pulse shrink-0" />}
                          <span>{isLandfallPt ? `🎯 ${label}` : label}</span>
                        </div>
                      </Tooltip>
                    )}
                    <Popup>
                      <div className="p-1 space-y-1 text-xs">
                        <p className="font-bold text-foreground">{pt.category}</p>
                        <p className="text-muted-foreground">Wind: <strong className="text-foreground">{pt.intensity_knots ?? "Not available"} KT ({(pt.intensity_knots == null ? null : Math.round(pt.intensity_knots * 1.852))} km/h)</strong></p>
                        <p className="text-muted-foreground">Fix: {pt.lat.toFixed(1)}°N, {pt.lon.toFixed(1)}°E</p>
                        {isLandfallPt && (
                          <p className="font-bold text-red-500 bg-red-500/10 p-1 rounded border border-red-500/20">
                            🎯 Landfall Coastal Crossing Fix
                          </p>
                        )}
                      </div>
                    </Popup>
                  </CircleMarker>
                </React.Fragment>
              );
            })}
          </>
        )}
      </MapContainer>
    </div>
  );
}

"use client";
import type { TrackPoint } from "@/types/api";
import React, { useState, useEffect, useRef } from "react";
import { 
  MapContainer, 
  TileLayer, 
  Polyline, 
  CircleMarker, 
  Polygon,
  Tooltip, 
  Popup,
  useMap, 
  ZoomControl 
} from "react-leaflet";
import { Layers, Zap, Navigation, Building2, ShieldAlert, ShieldCheck } from "lucide-react";
import "leaflet/dist/leaflet.css";
import L from "leaflet";
import { 
  POWER_SUBSTATIONS, 
  EVACUATION_ROUTES, 
  MEDICAL_SHELTERS, 
  COASTAL_INUNDATION_ZONES 
} from '@/lib/infrastructureData';



interface MapWidgetProps {
  points: TrackPoint[];
  systemName?: string;
}

const MAP_STYLES = {
  satellite: {
    name: 'Esri base imagery (not live telemetry)',
    url: 'https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}',
    attribution: 'Tiles &copy; Esri'
  },
  street: {
    name: 'IMD Chart (Street/Geo)',
    url: 'https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',
    attribution: '&copy; OpenStreetMap contributors &copy; IMD Best-Track'
  },
  dark: {
    name: 'Dark Tactical',
    url: 'https://server.arcgisonline.com/ArcGIS/rest/services/Canvas/World_Dark_Gray_Base/MapServer/tile/{z}/{y}/{x}',
    attribution: 'Tiles &copy; Esri'
  }
};

type MapStyleKey = keyof typeof MAP_STYLES;
type InfraFilter = 'all' | 'power' | 'roads' | 'shelters' | 'parametric';

function MapReCenter({ center }: { center: [number, number] }) {
  const map = useMap();
  React.useEffect(() => {
    map.setView(center, 5);
  }, [center, map]);
  return null;
}

export default function MapWidget({ points, systemName }: MapWidgetProps) {
  const [currentStyle, setCurrentStyle] = useState<MapStyleKey>('satellite');
  const [isLayerMenuOpen, setIsLayerMenuOpen] = useState(false);
  const [showInfra, setShowInfra] = useState(false);
  const [infraFilter, setInfraFilter] = useState<InfraFilter>('all');
  const layerMenuRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (layerMenuRef.current && !layerMenuRef.current.contains(event.target as Node)) {
        setIsLayerMenuOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  if (!points || points.length === 0) return null;

  const currentPoint = points.find((p) => p.time_offset_hours === 0) || points[points.length - 1] || points[0];

  const positions = points.map(p => [p.lat, p.lon] as [number, number]);
  const pastPoints = points.filter(p => !p.is_forecast);
  const futurePoints = points.filter(p => p.is_forecast);

  return (
    <div className="w-full h-full min-h-[520px] relative z-0">
      <style>{`
        .leaflet-top.leaflet-right {
          top: 60px !important;
          right: 16px !important;
        }
        .leaflet-control-zoom {
          margin: 0 !important;
          border: 1px solid rgba(255, 255, 255, 0.18) !important;
          background: rgba(9, 9, 11, 0.88) !important;
          backdrop-filter: blur(12px) !important;
          -webkit-backdrop-filter: blur(12px) !important;
          border-radius: 12px !important;
          overflow: hidden !important;
          box-shadow: 0 8px 24px rgba(0, 0, 0, 0.6) !important;
        }
        .leaflet-control-zoom a {
          background: transparent !important;
          color: #f4f4f5 !important;
          border-bottom: 1px solid rgba(255, 255, 255, 0.12) !important;
          width: 38px !important;
          height: 34px !important;
          line-height: 34px !important;
          font-size: 16px !important;
          font-weight: 600 !important;
          display: flex !important;
          align-items: center !important;
          justify-content: center !important;
          transition: all 0.15s ease !important;
        }
        .leaflet-control-zoom a:last-child {
          border-bottom: none !important;
        }
        .leaflet-control-zoom a:hover {
          background: rgba(255, 255, 255, 0.18) !important;
          color: #ffffff !important;
        }
        .leaflet-tooltip,
        .leaflet-tooltip.custom-tooltip {
          background: rgba(9, 9, 11, 0.94) !important;
          backdrop-filter: blur(10px) !important;
          -webkit-backdrop-filter: blur(10px) !important;
          border: 1px solid rgba(255, 255, 255, 0.15) !important;
          border-radius: 6px !important;
          box-shadow: 0 4px 14px rgba(0, 0, 0, 0.7) !important;
          color: #ffffff !important;
          font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, "Liberation Mono", monospace !important;
          font-size: 10px !important;
          font-weight: 700 !important;
          line-height: 1.2 !important;
          padding: 2px 6px !important;
          white-space: nowrap !important;
          pointer-events: none !important;
        }
        .leaflet-tooltip::before,
        .leaflet-tooltip::after,
        .leaflet-tooltip.custom-tooltip::before,
        .leaflet-tooltip.custom-tooltip::after {
          display: none !important;
          border: none !important;
        }
      `}</style>

      {/* Top Left Badge & Infrastructure Filter Pills */}
      <div className="absolute top-4 left-4 z-[1000] flex flex-col gap-2 pointer-events-auto">
        <div className="bg-card/90 backdrop-blur-md px-4 py-2 rounded-xl border border-border shadow-lg flex items-center gap-2.5">
          <div className="w-2.5 h-2.5 rounded-full bg-emerald-500 animate-pulse shrink-0" />
          <div>
            <h4 className="font-heading font-semibold text-xs text-foreground">
              INSAT-3DR & GEE Live Surveillance
            </h4>
            <p className="text-[10.5px] text-muted-foreground">
              {systemName ? `Tracking: ${systemName}` : "North Indian Ocean Basin"}
            </p>
          </div>
        </div>

        {/* Infrastructure Layer Toggle */}
        <div className="flex items-center gap-1 bg-background/90 backdrop-blur-md p-1 rounded-lg border border-border shadow-md text-xs">
          <button
            onClick={() => setShowInfra(!showInfra)}
            className={`px-2 py-0.5 rounded text-[11px] font-bold transition-all flex items-center gap-1 ${
              showInfra ? "bg-primary text-primary-foreground" : "text-muted-foreground hover:text-foreground"
            }`}
          >
            <ShieldCheck className="w-3 h-3" /> Scenario assets (unverified)
          </button>
          {showInfra && (
            <>
              <button
                onClick={() => setInfraFilter('all')}
                className={`px-1.5 py-0.5 rounded text-[10px] ${infraFilter === 'all' ? 'bg-secondary font-bold text-foreground' : 'text-muted-foreground'}`}
              >
                All
              </button>
              <button
                onClick={() => setInfraFilter('power')}
                className={`px-1.5 py-0.5 rounded text-[10px] flex items-center gap-0.5 ${infraFilter === 'power' ? 'bg-amber-500/20 text-amber-300 font-bold' : 'text-muted-foreground'}`}
              >
                <Zap className="w-2.5 h-2.5 text-amber-400" /> Grids
              </button>
              <button
                onClick={() => setInfraFilter('roads')}
                className={`px-1.5 py-0.5 rounded text-[10px] flex items-center gap-0.5 ${infraFilter === 'roads' ? 'bg-blue-500/20 text-blue-300 font-bold' : 'text-muted-foreground'}`}
              >
                <Navigation className="w-2.5 h-2.5 text-blue-400" /> Roads
              </button>
              <button
                onClick={() => setInfraFilter('shelters')}
                className={`px-1.5 py-0.5 rounded text-[10px] flex items-center gap-0.5 ${infraFilter === 'shelters' ? 'bg-emerald-500/20 text-emerald-300 font-bold' : 'text-muted-foreground'}`}
              >
                <Building2 className="w-2.5 h-2.5 text-emerald-400" /> Shelters
              </button>
            </>
          )}
        </div>
      </div>

      {/* Base Map Theme Switcher (Top-Right) */}
      <div className="absolute top-4 right-4 z-[1000] pointer-events-auto" ref={layerMenuRef}>
        <div className="relative">
          <button 
            onClick={() => setIsLayerMenuOpen(!isLayerMenuOpen)}
            className="bg-card/90 backdrop-blur-md p-2.5 rounded-xl border border-border shadow-lg hover:bg-secondary transition-colors flex items-center justify-center cursor-pointer text-foreground"
            title="Switch Map Layers"
          >
            <Layers className="w-4 h-4" />
          </button>
          {isLayerMenuOpen && (
            <div className="absolute top-full right-0 mt-2 bg-card/95 backdrop-blur-xl border border-border rounded-xl shadow-2xl overflow-hidden flex flex-col w-52 py-1 z-50 animate-in fade-in zoom-in-95 duration-150">
              <div className="px-3 py-1.5 text-[10px] font-bold uppercase tracking-wider text-muted-foreground border-b border-border">
                Base Map Theme
              </div>
              {Object.entries(MAP_STYLES).map(([key, style]) => (
                <button
                  key={key}
                  onClick={() => {
                    setCurrentStyle(key as MapStyleKey);
                    setIsLayerMenuOpen(false);
                  }}
                  className={`text-left px-3.5 py-2 text-xs transition-colors flex items-center justify-between cursor-pointer ${
                    currentStyle === key 
                      ? 'bg-primary/15 text-primary font-bold' 
                      : 'text-foreground hover:bg-secondary'
                  }`}
                >
                  <span>{style.name}</span>
                  {currentStyle === key && <span className="w-1.5 h-1.5 rounded-full bg-primary" />}
                </button>
              ))}
            </div>
          )}
        </div>
      </div>

      <MapContainer
        center={[currentPoint.lat, currentPoint.lon]}
        zoom={5}
        zoomControl={false}
        className="w-full h-full min-h-[520px] rounded-xl"
      >
        <ZoomControl position="topright" />
        <MapReCenter center={[currentPoint.lat, currentPoint.lon]} />

        <TileLayer
          attribution={MAP_STYLES[currentStyle].attribution}
          url={MAP_STYLES[currentStyle].url}
        />

        {/* ── Critical Infrastructure Layers ─────────────────────────────────── */}
        {showInfra && (
          <>
            <div className="absolute bottom-2 left-2 z-[1000] bg-background p-2 text-xs">ILLUSTRATIVE ASSETS — all coordinates and capacities unverified; road status unknown.</div>
            {/* Parametric Coastal Inundation Buffer Zones */}
            {(infraFilter === 'all' || infraFilter === 'parametric') && (
              COASTAL_INUNDATION_ZONES.map((zone, i) => (
                <Polygon
                  key={`inundation-${i}`}
                  positions={zone.polygon}
                  pathOptions={{
                    fillColor: "#06b6d4",
                    fillOpacity: 0.25,
                    color: "#0891b2",
                    weight: 2,
                    dashArray: "4, 4"
                  }}
                >
                  <Popup>
                    <div className="p-1 space-y-1 text-xs text-white">
                      <p className="font-bold text-cyan-400 flex items-center gap-1.5 text-sm">
                        <ShieldAlert className="w-4 h-4 text-cyan-400 shrink-0" />
                        <span>{zone.name}</span>
                      </p>
                      <p className="text-zinc-300 text-[11px]">Scenario depth: <strong className="text-white">{zone.depthM}</strong></p>
                      <p className="text-zinc-400 text-[10.5px]">Parametric Trigger: <span className="text-cyan-300 font-medium">No verified funding or insurance contract</span></p>
                    </div>
                  </Popup>
                  <Tooltip direction="center">
                    <span className="text-[10px] font-bold font-mono text-cyan-300 bg-zinc-950/80 px-1.5 py-0.5 rounded border border-cyan-500/40">
                      🌊 {zone.riskLevel}
                    </span>
                  </Tooltip>
                </Polygon>
              ))
            )}

            {/* Arterial Evacuation Routes */}
            {(infraFilter === 'all' || infraFilter === 'roads') && (
              EVACUATION_ROUTES.map((route, i) => (
                <Polyline
                  key={`route-${i}`}
                  positions={route.path}
                  pathOptions={{
                    color: route.floodRiskLevel.includes("Severe") ? "#ef4444" : "#3b82f6",
                    weight: 3.5,
                    opacity: 0.85
                  }}
                >
                  <Popup>
                    <div className="p-1.5 space-y-1.5 text-xs text-white">
                      <p className="font-bold text-white text-sm">{route.name}</p>
                      <p className="text-[11px] text-zinc-300">Scenario category: <strong className="text-white">{route.evacuationPriority}</strong></p>
                      <p className={`text-[11px] font-semibold ${route.floodRiskLevel.includes("Severe") ? "text-red-400" : "text-blue-400"}`}>
                        Scenario risk: {route.floodRiskLevel}
                      </p>
                    </div>
                  </Popup>
                  <Tooltip direction="top">
                    <span className="text-[10px] font-bold font-mono text-white bg-blue-900/90 px-1.5 py-0.5 rounded border border-blue-400/40">
                      🛣️ {route.highwayCode} (Evac Corridor)
                    </span>
                  </Tooltip>
                </Polyline>
              ))
            )}

            {/* Power Grid Substations */}
            {(infraFilter === 'all' || infraFilter === 'power') && (
              POWER_SUBSTATIONS.map((sub, i) => (
                <CircleMarker
                  key={`sub-${i}`}
                  center={[sub.lat, sub.lon]}
                  radius={6}
                  fillColor="#f59e0b"
                  color="#ffffff"
                  weight={1.5}
                  fillOpacity={0.95}
                >
                  <Popup>
                    <div className="p-1.5 space-y-1.5 text-xs text-white">
                      <div className="flex items-center gap-1.5 text-amber-400 font-bold text-sm">
                        <Zap className="w-4 h-4 shrink-0" />
                        <span>{sub.name}</span>
                      </div>
                      <p className="text-zinc-300 text-[11px]">Type: <strong className="text-white">{sub.type}</strong></p>
                      <p className="text-zinc-300 text-[11px]">Assumed capacity: <strong className="text-white">{sub.capacityMVA} MVA</strong></p>
                      <p className="text-zinc-300 text-[11px]">Coastal Distance: <strong className="text-white">{sub.coastalDistanceKm} km</strong> (Elev: {sub.elevationMeters}m)</p>
                      <span className="inline-block px-2.5 py-1 mt-1 rounded-md text-[10.5px] font-bold bg-amber-500/20 text-amber-300 border border-amber-500/40">
                        Criticality: {sub.criticality}
                      </span>
                    </div>
                  </Popup>
                  <Tooltip direction="top" offset={[0, -5]}>
                    <span className="text-[9.5px] font-bold font-mono text-amber-200 bg-zinc-950/90 px-1 py-0.5 rounded border border-amber-500/30">
                      ⚡ {sub.name.split(" ")[0]} ({sub.capacityMVA}MVA)
                    </span>
                  </Tooltip>
                </CircleMarker>
              ))
            )}

            {/* Medical Cyclone Shelters */}
            {(infraFilter === 'all' || infraFilter === 'shelters') && (
              MEDICAL_SHELTERS.map((shl, i) => (
                <CircleMarker
                  key={`shl-${i}`}
                  center={[shl.lat, shl.lon]}
                  radius={6}
                  fillColor="#10b981"
                  color="#ffffff"
                  weight={1.5}
                  fillOpacity={0.95}
                >
                  <Popup>
                    <div className="p-1.5 space-y-1.5 text-xs text-white">
                      <div className="flex items-center gap-1.5 text-emerald-400 font-bold text-sm">
                        <Building2 className="w-4 h-4 shrink-0" />
                        <span>{shl.name}</span>
                      </div>
                      <p className="text-zinc-300 text-[11px]">Type: <strong className="text-white">{shl.type}</strong></p>
                      <p className="text-zinc-300 text-[11px]">Assumed capacity: <strong className="text-white">{shl.capacityPersons.toLocaleString()} persons</strong></p>
                      <p className="text-zinc-300 text-[11px]">Assumed beds: <strong className="text-white">{shl.medicalBeds} Beds</strong></p>
                      <p className="text-zinc-300 text-[10.5px]">Backup Power: <strong className="text-white">{"Unavailable"}</strong></p>
                      <span className="inline-block px-2.5 py-1 mt-1 rounded-md text-[10.5px] font-bold bg-emerald-500/20 text-emerald-300 border border-emerald-500/40">
                        Status: {"Operational status not verified"}
                      </span>
                    </div>
                  </Popup>
                  <Tooltip direction="top" offset={[0, -5]}>
                    <span className="text-[9.5px] font-bold font-mono text-emerald-200 bg-zinc-950/90 px-1 py-0.5 rounded border border-emerald-500/30">
                      🏥 {shl.name.split(" ")[0]} ({shl.capacityPersons}p)
                    </span>
                  </Tooltip>
                </CircleMarker>
              ))
            )}
          </>
        )}

        {/* ── Cyclone Trajectory Segments ─────────────────────────────────── */}
        {positions.length > 1 && (
          <Polyline
            positions={positions}
            pathOptions={{ color: "#3b82f6", weight: 3, opacity: 0.8 }}
          />
        )}

        {/* Past points */}
        {pastPoints.map((pt, idx) => (
          <CircleMarker
            key={`past-${idx}`}
            center={[pt.lat, pt.lon]}
            radius={4.5}
            pathOptions={{
              color: "#ffffff",
              fillColor: "#3b82f6",
              fillOpacity: 1,
              weight: 1.5,
            }}
          >
            <Tooltip permanent direction="bottom" offset={[0, 8]} className="custom-tooltip">
              <span>{pt.time_offset_hours === 0 ? "Now" : `${pt.time_offset_hours}h`}</span>
            </Tooltip>
          </CircleMarker>
        ))}

        {/* Current point */}
        <CircleMarker
          center={[currentPoint.lat, currentPoint.lon]}
          radius={8}
          pathOptions={{
            color: "#ffffff",
            fillColor: "#ef4444",
            fillOpacity: 1,
            weight: 2.5,
          }}
        >
          <Tooltip permanent direction="top" offset={[0, -10]} className="custom-tooltip">
            <span className="text-red-400 font-bold">{currentPoint.intensity_knots ?? "Not available"} KT ({currentPoint.provenance ?? "UNKNOWN"})</span>
          </Tooltip>
        </CircleMarker>

        {/* Future points */}
        {futurePoints.map((pt, idx) => (
          <CircleMarker
            key={`future-${idx}`}
            center={[pt.lat, pt.lon]}
            radius={5.5}
            pathOptions={{
              color: "#ffffff",
              fillColor: pt.is_landfall ? "#dc2626" : "#ef4444",
              fillOpacity: 1,
              weight: pt.is_landfall ? 3 : 1.5,
            }}
          >
            <Tooltip permanent direction="bottom" offset={[0, 8]} className="custom-tooltip">
              <span>{pt.is_landfall ? `🎯 Landfall (+${pt.time_offset_hours}h)` : `+${pt.time_offset_hours}h (Kinematic)`}</span>
            </Tooltip>
          </CircleMarker>
        ))}
      </MapContainer>
    </div>
  );
}

"use client";
import { useMounted } from "@/hooks/useBrowserState";

import React, { useEffect, useState, useId } from "react";
import { useTheme } from "next-themes";

interface NeonThemeToggleProps {
  /** Optional CSS scaling or wrapper classes */
  className?: string;
  /** Scale factor: "sm" (0.55), "md" (0.75), "lg" (1.0) */
  size?: "sm" | "md" | "lg";
}

export function NeonThemeToggle({ className = "", size = "sm" }: NeonThemeToggleProps) {
  const mounted = useMounted();
  const { theme, setTheme } = useTheme();
  const rawId = useId();
  const id = rawId.replace(/:/g, "_");



  // When dark, checkbox is checked (Neon Green Power ON)
  const isDark = mounted ? theme === "dark" : true;

  const handleToggle = (e: React.ChangeEvent<HTMLInputElement>) => {
    setTheme(e.target.checked ? "dark" : "light");
  };

  const scaleMap = {
    sm: "scale-[0.55] origin-center",
    md: "scale-[0.75] origin-center",
    lg: "scale-100 origin-center",
  };

  const containerDimensions = {
    sm: "w-[56px] h-[34px]",
    md: "w-[76px] h-[46px]",
    lg: "w-[100px] h-[60px]",
  };

  return (
    <div
      className={`relative inline-flex items-center justify-center select-none ${containerDimensions[size]} ${className}`}
      title={mounted ? (isDark ? "Dark Cyber Mode Active (Click for Light Mode)" : "Light Mode Active (Click for Dark Mode)") : "Toggle Theme"}
    >
      <div className={`shrink-0 transform ${scaleMap[size]}`}>
        <label className="switch" htmlFor={`switch-${id}`}>
          <input
            id={`switch-${id}`}
            className="switch__input"
            type="checkbox"
            role="switch"
            checked={isDark}
            onChange={handleToggle}
            aria-label="Toggle dark/light theme"
          />
          <span className="switch__base-outer"></span>
          <span className="switch__base-inner"></span>
          <svg
            className="switch__base-neon"
            viewBox="0 0 40 24"
            width="60"
            height="36"
            xmlns="http://www.w3.org/2000/svg"
            aria-hidden="true"
          >
            <defs>
              <filter id={`glow-${id}`}>
                <feGaussianBlur result="coloredBlur" stdDeviation="1"></feGaussianBlur>
                <feMerge>
                  <feMergeNode in="coloredBlur"></feMergeNode>
                  <feMergeNode in="SourceGraphic"></feMergeNode>
                </feMerge>
              </filter>
              <linearGradient id={`g1-${id}`} x1="0" y1="0" x2="1" y2="0">
                <stop offset="0%" stopColor="hsl(123,90%,70%)"></stop>
                <stop offset="100%" stopColor="hsl(168,90%,70%)"></stop>
              </linearGradient>
              <linearGradient id={`g2-${id}`} x1="0.7" y1="0" x2="0.3" y2="1">
                <stop offset="25%" stopColor="hsla(123,90%,70%,0)"></stop>
                <stop offset="50%" stopColor="hsla(123,90%,70%,0.3)"></stop>
                <stop offset="100%" stopColor="hsla(168,90%,70%,0.3)"></stop>
              </linearGradient>
            </defs>
            <path
              fill="none"
              filter={`url(#glow-${id})`}
              stroke={`url(#g1-${id})`}
              strokeWidth="1"
              strokeDasharray="0 104.26 0"
              strokeDashoffset="0.01"
              strokeLinecap="round"
              d="m.5,12C.5,5.649,5.649.5,12,.5h16c6.351,0,11.5,5.149,11.5,11.5s-5.149,11.5-11.5,11.5H12C5.649,23.5.5,18.351.5,12Z"
            ></path>
          </svg>
          <span className="switch__knob-shadow"></span>
          <span className="switch__knob-container">
            <span className="switch__knob">
              <svg
                className="switch__knob-neon"
                viewBox="0 0 48 48"
                width="36"
                height="36"
                xmlns="http://www.w3.org/2000/svg"
                aria-hidden="true"
              >
                <circle
                  fill="none"
                  stroke={`url(#g2-${id})`}
                  strokeDasharray="0 90.32 0 54.19"
                  strokeLinecap="round"
                  strokeWidth="1"
                  r="23"
                  cx="24"
                  cy="24"
                  transform="rotate(-112.5,24,24)"
                ></circle>
              </svg>
            </span>
          </span>
          <span className="switch__led"></span>
          <span className="switch__text">Power</span>
        </label>
      </div>
    </div>
  );
}

"use client";

import React from "react";
import Link from "next/link";
import { usePathname } from "next/navigation";
import { Activity, UploadCloud, History, FileText, Settings, Wind, LogOut, GitCompare, Building2 } from "lucide-react";
import { clsx, type ClassValue } from "clsx";
import { twMerge } from "tailwind-merge";
import { CycloneLogo } from "@/components/CycloneLogo";

import { useUser, useClerk } from "@clerk/nextjs";

function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

import { useLanguage } from "@/context/LanguageContext";

export const navItems = [
  { key: "live_monitoring", name: "Live Monitoring", href: "/dashboard", icon: Activity },
  { key: "classification", name: "Classification", href: "/classification", icon: UploadCloud },
  { key: "historical_archive", name: "Historical Archive", href: "/archive", icon: History },
  { key: "storm_comparison", name: "Storm Comparison", href: "/compare", icon: GitCompare },
  { key: "track_forecast", name: "Track Forecast", href: "/forecast", icon: Wind },
  { key: "alerts_reports", name: "Alerts & Reports", href: "/reports", icon: FileText },
  { key: "infrastructure_relief", name: "Infrastructure & Relief", href: "/infrastructure", icon: Building2 },
  { key: "settings", name: "Settings", href: "/settings", icon: Settings },
];

export function Sidebar() {
  const pathname = usePathname();
  const { user: clerkUser, isLoaded } = useUser();
  const { signOut } = useClerk();
  const { t } = useLanguage();

  const isAuthenticated = Boolean(isLoaded && clerkUser);
  const displayName = isAuthenticated
    ? (clerkUser?.fullName || clerkUser?.primaryEmailAddress?.emailAddress?.split("@")[0] || "Officer")
    : "Guest Visitor";
  const displayRole = isAuthenticated ? "SIGNED IN" : "PUBLIC VIEWER";
  const displayInitials = isAuthenticated ? displayName.slice(0, 2).toUpperCase() : "GV";
  const avatarUrl = isAuthenticated ? clerkUser?.imageUrl : null;

  const handleLogout = async () => {
    if (typeof window !== "undefined") {
      localStorage.removeItem("cyclonet_user");
      localStorage.removeItem("cyclonet_auth_token");
      if (clerkUser) {
        await signOut({ redirectUrl: "/" });
      } else {
        window.location.href = "/";
      }
    }
  };

  return (
    <aside className="w-64 hidden lg:flex flex-col h-screen fixed left-0 top-0 sidebar-mesh border-r border-border">
      <div className="p-6 flex items-center justify-between">
        <Link href="/dashboard" className="flex items-center gap-3 group">
          <div className="relative flex items-center justify-center group-hover:scale-105 transition-transform">
            <CycloneLogo size={32} />
          </div>
          <span className="font-heading font-extrabold text-xl bg-gradient-to-r from-blue-400 via-sky-300 to-indigo-400 bg-clip-text text-transparent tracking-tight">
            CycloNet
          </span>
        </Link>
      </div>

      <nav className="flex-1 px-4 py-2 space-y-1 overflow-y-auto scrollbar-hide">
        {navItems.map((item) => {
          const isActive = pathname === item.href;
          const Icon = item.icon;
          const translatedName = t(item.key) || item.name;
          return (
            <Link
              key={item.name}
              href={item.href}
              className={cn(
                "flex items-center gap-3 px-3 py-2.5 rounded-lg text-sm font-medium transition-all duration-200 group relative overflow-hidden",
                isActive
                  ? "text-slate-900 dark:text-white bg-slate-900/10 dark:bg-white/10 shadow-xs font-semibold"
                  : "text-slate-600 dark:text-zinc-400 hover:text-slate-900 dark:hover:text-white hover:bg-slate-900/5 dark:hover:bg-white/5"
              )}
            >
              {isActive && (
                <div className="absolute inset-0 bg-slate-900/[0.08] dark:bg-white/[0.08] rounded-lg -z-10" />
              )}
              {isActive && (
                <div className="absolute left-0 top-1/2 -translate-y-1/2 w-1 h-5 bg-slate-900 dark:bg-white rounded-r-full" />
              )}
              <Icon className={cn("w-5 h-5 transition-colors", isActive ? "text-slate-900 dark:text-white" : "text-slate-500 group-hover:text-slate-900 dark:text-zinc-400 dark:group-hover:text-white")} />
              <span>{translatedName}</span>
            </Link>
          );
        })}
      </nav>

      {/* Officer Profile & Logout Bottom Bar (directs to auth/login) */}
      <div className="p-3 border-t border-border mt-auto">
        <div className="flex items-center justify-between p-2 rounded-xl bg-slate-900/[0.03] dark:bg-white/[0.03] hover:bg-slate-900/[0.06] dark:hover:bg-white/[0.06] transition-colors">
          <div className="flex items-center gap-3 min-w-0">
            {avatarUrl ? (
              <img
                src={avatarUrl}
                alt={displayName}
                className="w-9 h-9 rounded-full object-cover shadow-xs shrink-0 ring-2 ring-indigo-500/20"
              />
            ) : (
              <div className="w-9 h-9 rounded-full bg-gradient-to-tr from-indigo-600 to-violet-500 text-white font-bold text-xs flex items-center justify-center shadow-xs shrink-0 ring-2 ring-indigo-500/20">
                {displayInitials}
              </div>
            )}
            <div className="flex flex-col min-w-0">
              <span className="text-xs sm:text-sm font-bold text-slate-900 dark:text-white truncate leading-tight">
                {displayName}
              </span>
              <span className="text-[10px] font-semibold text-slate-500 dark:text-zinc-400 uppercase tracking-wider truncate mt-0.5">
                {displayRole}
              </span>
            </div>
          </div>

          <div className="flex items-center gap-1 shrink-0 ml-2">
            <Link
              href="/settings"
              className="p-1.5 rounded-lg text-slate-500 hover:text-slate-900 dark:text-zinc-400 dark:hover:text-white hover:bg-slate-900/10 dark:hover:bg-white/10 transition-colors"
              title="Settings"
              aria-label="Settings"
            >
              <Settings className="w-4 h-4" />
            </Link>
            
            <button
              onClick={handleLogout}
              className="p-1.5 rounded-lg text-slate-500 hover:text-rose-600 dark:text-zinc-400 dark:hover:text-rose-400 hover:bg-rose-500/10 transition-colors cursor-pointer"
              title="Sign Out to Landing Page"
              aria-label="Sign Out to Landing Page"
            >
              <LogOut className="w-4 h-4" />
            </button>
          </div>
        </div>
      </div>
    </aside>
  );
}

"use client";

import React from "react";
import { GlassPanel } from "./GlassPanel";
import { MicroLabel } from "./MicroLabel";
import { PillButton } from "./PillButton";
import { ArrowRight, Waves, ShieldAlert, CheckCircle2, Cpu } from "lucide-react";
import { motion } from "framer-motion";

export function FeatureSpotlight1() {
  return (
    <section className="py-24 bg-bg-elevated text-text-primary relative overflow-hidden border-t border-surface-border transition-colors duration-300">
      <div className="container max-w-[1250px] mx-auto px-4 relative z-10">
        <div className="grid lg:grid-cols-2 gap-16 items-center">
          
          {/* Text Content (Left) */}
          <motion.div 
            initial={{ opacity: 0, x: -30 }}
            whileInView={{ opacity: 1, x: 0 }}
            viewport={{ once: true, margin: "-100px" }}
            transition={{ duration: 0.6 }}
            className="max-w-xl"
          >
            <MicroLabel className="mb-4 inline-block px-3 py-1 bg-sky-500/10 text-sky-500 dark:text-sky-400 rounded-full border border-sky-500/20">
              Parametric Hydrodynamic Engine
            </MicroLabel>
            <h2 className="text-3xl md:text-5xl font-black font-heading tracking-tight text-text-primary mb-6">
              Simulate compound coastal storm surge. <br/>
              <span className="text-transparent bg-clip-text bg-gradient-to-r from-sky-400 via-blue-500 to-indigo-500">
                Before the storm eye reaches shore.
              </span>
            </h2>
            <p className="text-sm md:text-base text-text-muted leading-relaxed mb-6">
              CycloNet&apos;s parametric surge estimator (Jelesnianski formulation) models oceanic water pileup by coupling central barometric pressure deficits with bathymetric wind stress on shallow continental shelves and astronomical spring tide stages.
            </p>

            <div className="p-4 rounded-xl bg-card/70 border border-border mb-8 space-y-2">
              <div className="text-xs font-mono font-bold text-sky-400 flex items-center gap-1.5">
                <Cpu className="w-3.5 h-3.5" />
                <span>Parametric Surge Formulation (Jelesnianski)</span>
              </div>
              <p className="text-xs font-mono text-text-primary font-semibold">
                S_peak = α · ΔP + β · V_max² · cos(θ_coast) + H_tide
              </p>
              <p className="text-[11px] text-text-muted leading-normal">
                Uses assumed shelf depth and coastal slope. No surveyed bathymetry, sampled DEM, or independently calibrated uncertainty is available.
              </p>
            </div>

            <PillButton 
              variant="ghost" 
              icon={ArrowRight}
              onClick={() => window.location.href = "/infrastructure"}
              className="border-surface-border bg-card text-text-primary hover:bg-card/80 cursor-pointer"
            >
              Open surge scenarios
            </PillButton>
          </motion.div>

          {/* Visual (Right) */}
          <motion.div 
            initial={{ opacity: 0, x: 30 }}
            whileInView={{ opacity: 1, x: 0 }}
            viewport={{ once: true, margin: "-100px" }}
            transition={{ duration: 0.6, delay: 0.2 }}
            className="relative"
          >
            <div className="relative rounded-2xl p-2 bg-surface-glass border border-surface-border shadow-xl backdrop-blur-xl">
