          <div className="flex flex-wrap items-center justify-center gap-3 mb-10">
            {PILLARS.map((pillar) => {
              const Icon = pillar.icon;
              const isSelected = activePillar.id === pillar.id;
              return (
                <button
                  key={pillar.id}
                  onClick={() => setActivePillar(pillar)}
