interface LanguageContextType {
  language: SupportedLanguage;
  setLanguage: (lang: SupportedLanguage) => void;
  t: (key: string) => string;
}

const LanguageContext = createContext<LanguageContextType>({
  language: "en",
  setLanguage: () => {},
  t: (key: string) => key,
});

export function LanguageProvider({ children }: { children: React.ReactNode }) {
  const [storedLanguage, setStoredLanguage] = useStoredValue("cyclonet_language", "en");
  const language: SupportedLanguage = storedLanguage && storedLanguage in TRANSLATIONS ? storedLanguage as SupportedLanguage : "en";
  const setLanguage = (lang: SupportedLanguage) => setStoredLanguage(lang);

  const t = (key: string): string => {
    const langDict = TRANSLATIONS[language];
    if (langDict && langDict[key]) {
      return langDict[key];
    }
    // Fallback to English
    return TRANSLATIONS.en[key] || key;
  };

  return (
    <LanguageContext.Provider value={{ language, setLanguage, t }}>
      {children}
    </LanguageContext.Provider>
  );
}

export function useLanguage() {
  return useContext(LanguageContext);
}

"use client";
import { useState, useEffect, useCallback } from "react";

export type DataSourceType = "IMD" | "JTWC" | "CUSTOM";

export const STORAGE_KEY_SOURCE = "cyclonet_data_source";
export const STORAGE_KEY_CUSTOM_URL = "cyclonet_custom_api_url";
export const CYCLONET_SOURCE_EVENT = "cyclonet:data-source-changed";

export interface DataSourceBadge {
  type: DataSourceType;
  label: string;
  shortLabel: string;
  avgWindow: string;
  badgeClass: string;
  scaleName: string;
  desc: string;
}

export function useDataSource() {
  const [dataSource, setDataSourceState] = useState<DataSourceType>(() => {
    if (typeof window !== "undefined") {
      const stored = localStorage.getItem(STORAGE_KEY_SOURCE);
      if (stored === "JTWC" || stored === "CUSTOM" || stored === "IMD") {
        return stored as DataSourceType;
      }
    }
    return "IMD";
  });
  const [customApiUrl, setCustomApiUrlState] = useState<string>(() => {
    if (typeof window !== "undefined") {
      return localStorage.getItem(STORAGE_KEY_CUSTOM_URL) || "http://localhost:8000/api";
    }
    return "http://localhost:8000/api";
  });

  const syncState = useCallback(() => {
    if (typeof window !== "undefined") {
      const stored = localStorage.getItem(STORAGE_KEY_SOURCE);
      if (stored === "JTWC" || stored === "CUSTOM" || stored === "IMD") {
        setDataSourceState(stored as DataSourceType);
      } else {
        setDataSourceState("IMD");
      }
      const customUrl = localStorage.getItem(STORAGE_KEY_CUSTOM_URL);
      if (customUrl) {
        setCustomApiUrlState(customUrl);
      }
    }
  }, []);

  useEffect(() => {
    const handleCustomEvent = () => syncState();
    const handleStorageEvent = (e: StorageEvent) => {
      if (e.key === STORAGE_KEY_SOURCE || e.key === STORAGE_KEY_CUSTOM_URL) {
        syncState();
      }
    };

    window.addEventListener(CYCLONET_SOURCE_EVENT, handleCustomEvent);
    window.addEventListener("storage", handleStorageEvent);

    return () => {
      window.removeEventListener(CYCLONET_SOURCE_EVENT, handleCustomEvent);
      window.removeEventListener("storage", handleStorageEvent);
    };
  }, [syncState]);

  const setDataSource = useCallback((source: DataSourceType) => {
    if (typeof window !== "undefined") {
      localStorage.setItem(STORAGE_KEY_SOURCE, source);
      setDataSourceState(source);
      window.dispatchEvent(new CustomEvent(CYCLONET_SOURCE_EVENT, { detail: { source } }));
    }
  }, []);

  const setCustomApiUrl = useCallback((url: string) => {
    if (typeof window !== "undefined") {
      localStorage.setItem(STORAGE_KEY_CUSTOM_URL, url);
      setCustomApiUrlState(url);
      window.dispatchEvent(new CustomEvent(CYCLONET_SOURCE_EVENT, { detail: { customApiUrl: url } }));
    }
  }, []);

  // ── Conversion Utilities ──────────────────────────────────────────────────

  const getConvertedKnots = useCallback((baseKnots: number | null | undefined, rawJtwcKnots?: number): number | null => {
    // If genuine JTWC ATCF/TCFA bulletined wind telemetry is present, use it directly (Fix #41)
    if (rawJtwcKnots != null && Number.isFinite(rawJtwcKnots)) return rawJtwcKnots;
    if (baseKnots == null || !Number.isFinite(baseKnots)) return null;
    // Display preferences cannot manufacture another agency's measurement.
    return baseKnots;
  }, [dataSource]);

  const getConvertedKmh = useCallback((baseKnots: number | null | undefined): number | null => {
    const kts = getConvertedKnots(baseKnots);
    return kts == null ? null : Math.round(kts * 1.852);
  }, [getConvertedKnots]);

  const getConvertedGusts = useCallback((_baseKnots: number | null | undefined): number | null => null, []);

  const getConvertedCategory = useCallback((baseKnots: number | null | undefined, fallback?: string): string => {
    const kts = getConvertedKnots(baseKnots);

    if (kts == null) return "Not available";
    if (dataSource === "JTWC") {
      if (kts < 34) return "Tropical Depression";
      if (kts < 64) return "Tropical Storm";
      if (kts < 83) return "Category 1 Cyclone";
      if (kts < 96) return "Category 2 Cyclone";
      if (kts < 113) return "Category 3 Major Cyclone";
      if (kts < 137) return "Category 4 Major Cyclone";
      return "Category 5 Super Cyclone";
    }

    // Default IMD Standard
    if (kts < 17) return "Low Pressure Area";
    if (kts < 28) return "Depression";
    if (kts < 34) return "Deep Depression";
    if (kts < 48) return "Cyclonic Storm";
    if (kts < 64) return "Severe Cyclonic Storm";
    if (kts < 90) return "Very Severe Cyclonic Storm";
    if (kts < 120) return "Extremely Severe Cyclonic Storm";
    return "Super Cyclonic Storm";
  }, [dataSource, getConvertedKnots]);

  const getSourceBadge = useCallback((): DataSourceBadge => {
    if (dataSource === "JTWC") {
      return {
        type: "JTWC",
        label: "JTWC category display (not a source observation)",
        shortLabel: "JTWC (1-min)",
        avgWindow: "Source averaging period unchanged",
        badgeClass: "bg-blue-500/15 text-blue-400 border-blue-500/30",
        scaleName: "Saffir-Simpson (Cat 1–5)",
        desc: "Category display only; measured wind is preserved without an assumed averaging-period conversion."
      };
    }
    if (dataSource === "CUSTOM") {
      return {
        type: "CUSTOM",
        label: "Custom API Endpoint",
        shortLabel: "Custom API",
        avgWindow: "User Defined",
        badgeClass: "bg-purple-500/15 text-purple-400 border-purple-500/30",
        scaleName: "Custom Research Scale",
        desc: "Local or experimental forecasting model endpoint."
      };
    }
    return {
      type: "IMD",
      label: "IMD Standard (3-Min Avg)",
      shortLabel: "IMD (3-min)",
      avgWindow: "3-Minute Sustained (Standard)",
      badgeClass: "bg-emerald-500/15 text-emerald-400 border-emerald-500/30",
      scaleName: "WMO RSMC New Delhi Scale",
      desc: "India Meteorological Department standard using 3-minute sustained wind measurements."
    };
  }, [dataSource]);

  return {
    dataSource,
    customApiUrl,
    setDataSource,
    setCustomApiUrl,
    getConvertedKnots,
    getConvertedKmh,
    getConvertedGusts,
    getConvertedCategory,
    getSourceBadge,
  };
}

export class ApiClientError extends Error {
  status: number;
  retryAfter?: number;
  detail?: string;

  constructor(message: string, status: number, retryAfter?: number, detail?: string) {
    super(message);
    this.name = "ApiClientError";
    this.status = status;
    this.retryAfter = retryAfter;
    this.detail = detail;
  }
}

const isProd = process.env.NODE_ENV === "production";
const defaultUrl = isProd ? "https://cyclonet-backend.onrender.com" : "http://localhost:8000";
const rawUrl = process.env.NEXT_PUBLIC_API_URL || defaultUrl;
let cleaned = rawUrl.replace(/\/+$/, "").replace(/\/api$/, "");
if (cleaned && !cleaned.startsWith("http://") && !cleaned.startsWith("https://")) {
  cleaned = `https://${cleaned}`;
}
export const API_BASE_URL = cleaned;

/**
 * Dynamic API Base URL resolver that respects user-configured CUSTOM data source in Settings (Fix #37, UI-07).
 */
export function getApiBaseUrl(): string {
  if (typeof window !== "undefined") {
    try {
      const source = localStorage.getItem("cyclonet_data_source");
      if (source === "CUSTOM") {
        const customUrl = localStorage.getItem("cyclonet_custom_api_url");
        if (customUrl && customUrl.trim()) {
          let clean = customUrl.trim().replace(/\/+$/, "").replace(/\/api$/, "");
          if (clean && !clean.startsWith("http://") && !clean.startsWith("https://")) {
            clean = `https://${clean}`;
          }
          if (clean) return clean;
        }
      }
      // When browsing locally on localhost or 127.0.0.1, always prioritize the local backend
      // so local development never fails against sleeping or unconfigured cloud services.
      if (window.location.hostname === "localhost" || window.location.hostname === "127.0.0.1") {
        if (process.env.NEXT_PUBLIC_API_URL && (process.env.NEXT_PUBLIC_API_URL.includes("localhost") || process.env.NEXT_PUBLIC_API_URL.includes("127.0.0.1"))) {
          return process.env.NEXT_PUBLIC_API_URL.replace(/\/+$/, "").replace(/\/api$/, "");
        }
        return "http://localhost:8000";
      }
    } catch {
      // Fallback on restricted browser environments or SSR
    }
  }
  return API_BASE_URL;
}

let memoryToken: string | null = null;
let tokenProvider: (() => Promise<string | null>) | null = null;
export function setAuthTokenProvider(provider: (() => Promise<string | null>) | null) { tokenProvider = provider; }
export function getStoredAuthToken(): string | null { return memoryToken; }
export function setStoredAuthToken(token: string, _persistent = false): void {
  memoryToken = token;
  if (typeof window !== "undefined") {
    localStorage.removeItem("cyclonet_auth_token");
    sessionStorage.removeItem("cyclonet_auth_token");
  }
}
export function clearStoredAuthToken(): void {
  memoryToken = null;
  if (typeof window !== "undefined") {
    localStorage.removeItem("cyclonet_auth_token");
    sessionStorage.removeItem("cyclonet_auth_token");
  }
}

export function isTrustedOrigin(url: string): boolean {
  try {
    const parsed = new URL(url, typeof window !== "undefined" ? window.location.origin : "http://localhost:3000");
    const currentOrigin = typeof window !== "undefined" ? window.location.origin : "http://localhost:3000";
    if (isProd && parsed.protocol !== "https:") return false;
    if (parsed.origin === currentOrigin) return true;

    // Compare against configured first-party backend base URL
    const backendOrigin = new URL(API_BASE_URL).origin;
    if (parsed.origin === backendOrigin) return true;

    // Allow localhost / loopback for local development
    if (!isProd && (parsed.hostname === "localhost" || parsed.hostname === "127.0.0.1")) {
      return true;
    }
    return false;
  } catch {
    return false;
  }
}

/**
 * Robust fetch wrapper with timeout, exponential backoff retries with jitter,
 * authentication header attachment, and Retry-After handling (UI-01, SEC-05, SEC-06, FIX-04).
 */
export async function apiFetch<T = unknown>(
  endpoint: string,
  options: RequestInit & { token?: string; timeoutMs?: number; maxRetries?: number } = {}
): Promise<T> {
  const {
    token,
    timeoutMs = 12000,
    maxRetries = 2,
    ...fetchOptions
  } = options;

  const baseUrl = getApiBaseUrl();
  const url = endpoint.startsWith("http") ? endpoint : `${baseUrl}${endpoint.startsWith("/") ? "" : "/"}${endpoint}`;
  const method = (fetchOptions.method || "GET").toUpperCase();
  const isIdempotent = ["GET", "HEAD", "OPTIONS"].includes(method);

  const headers = new Headers(fetchOptions.headers || {});
  const authToken = isTrustedOrigin(url) ? (token || await tokenProvider?.() || getStoredAuthToken()) : null;

  // FIX 04: Centralized origin check on Authorization headers
  if (headers.has("Authorization")) {
    if (!isTrustedOrigin(url)) {
      console.warn(`[Security] Stripped explicitly supplied Authorization header destined for untrusted origin: ${url}`);
      headers.delete("Authorization");
    }
  } else if (authToken) {
    if (isTrustedOrigin(url)) {
      headers.set("Authorization", `Bearer ${authToken}`);
    } else {
      console.warn(`[Security] Withheld Bearer token from unverified origin: ${url}`);
    }
  }

  if (!isTrustedOrigin(url)) {
    headers.delete("X-Admin-Key");
    fetchOptions.credentials = "omit";
  }
  let attempt = 0;
  let lastError: unknown = null;

  while (attempt <= (isIdempotent ? maxRetries : 0)) {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), timeoutMs);

    try {
      const response = await fetch(url, {
        ...fetchOptions,
        headers,
        signal: fetchOptions.signal ? AbortSignal.any([fetchOptions.signal, controller.signal]) : controller.signal,
        redirect: "error",
      });
      clearTimeout(timeoutId);

      if (response.status === 429) {
        const retryHeader = response.headers.get("Retry-After");
        const retryAfter = retryHeader ? parseInt(retryHeader, 10) : 60;
        let detail = "Too Many Requests (Rate limit reached)";
        try {
          const body = await response.json();
          if (body?.detail) detail = body.detail;
        } catch {
          // ignore json parse error
        }
        throw new ApiClientError(detail, 429, retryAfter, detail);
      }

      if (!response.ok) {
        let detail = `HTTP ${response.status}: ${response.statusText}`;
        try {
          const body = await response.json();
          if (body?.detail) detail = typeof body.detail === "string" ? body.detail : JSON.stringify(body.detail);
        } catch {
          // ignore
        }

        // Retry on server errors if idempotent
        if (isIdempotent && [502, 503, 504].includes(response.status) && attempt < maxRetries) {
          attempt++;
          const jitter = Math.random() * 300;
          await new Promise((r) => setTimeout(r, 800 * Math.pow(2, attempt) + jitter));
          continue;
        }

        throw new ApiClientError(detail, response.status, undefined, detail);
      }

      return (await response.json()) as T;
    } catch (err: unknown) {
      clearTimeout(timeoutId);
      if (err instanceof ApiClientError) {
        throw err;
      }
      lastError = err;
      if (isIdempotent && attempt < maxRetries) {
        attempt++;
        const jitter = Math.random() * 300;
        await new Promise((r) => setTimeout(r, 800 * Math.pow(2, attempt) + jitter));
      } else {
        break;
      }
    }
  }

  throw lastError || new ApiClientError(`Failed request to ${url}`, 0);
}

export async function fetchWithTimeout(
  url: string,
  options: RequestInit = {},
  timeoutMs: number = 15000
): Promise<Response> {
  const controller = new AbortController();
  const id = setTimeout(() => controller.abort(), timeoutMs);

  try {
    const response = await fetch(url, {
      ...options,
      signal: options.signal || controller.signal,
    });
    clearTimeout(id);
    return response;
  } catch (error: unknown) {
    clearTimeout(id);
    throw error;
  }
}

export async function fetchWithRetry(
  url: string,
  options: RequestInit = {},
  maxRetries: number = 2,
  timeoutMs: number = 12000
): Promise<Response> {
  const method = (options.method || "GET").toUpperCase();
  const isIdempotent = ["GET", "HEAD"].includes(method);
  const actualRetries = isIdempotent ? maxRetries : 0;

  let lastError: unknown = null;
  for (let attempt = 0; attempt <= actualRetries; attempt++) {
    try {
      const res = await fetchWithTimeout(url, options, timeoutMs);
      if (res.ok || (res.status < 500 && res.status !== 429)) {
        return res;
      }
      if (res.status === 429) {
        return res;
      }
    } catch (err) {
      lastError = err;
      if (attempt < actualRetries) {
        const jitter = Math.random() * 200;
        await new Promise((r) => setTimeout(r, 1000 * Math.pow(2, attempt) + jitter));
      }
    }
  }
  throw lastError || new Error(`Failed to fetch ${url} after ${actualRetries} retries`);
}

